ventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.04), BlocDelta(blocId = BlocId.HISPANIC, margin = 0.02), BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = -0.02)), salienceDeltas = mapOf("economy" to 0.04), momentum = 1.0, narrative = 2.0), resultText = "The restraint keeps the suburbs in reach, and your base wonders why you went soft.")), oncePerGame = true),
