    GameEvent(id = "h20_convention", title = "Two Conventions, One Pandemic", prompt = "The conventions are done. Biden's beamed in from a near-empty hall in Wilmington, Trump's staged on the White House South Lawn. Modest bounces, locked-in bases. Where do you point the campaign now?", subject = "both", trigger = EventTrigger.Scheduled(turn = 0), choices = listOf(EventChoice(id = "d_sunbelt", text = "Expand into the Sun Belt: chase Arizona, Georgia, North Carolina.", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.HISPANIC, margin = 0.04), BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = 0.03), BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.03)), momentum = 3.0, narrative = 2.0), resultText = "You stretch the map. The Sun Belt is suddenly live, but you're spread thin."), EventChoice(id = "d_bluewall", text = "Rebuild the blue wall: turn out Black and union voters in the Midwest.", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.BLACK, margin = 0.05, enthusiasm = 0.02), BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.03)), momentum = 2.0), resultText = "You plant the flag in the Rust Belt and cede the Sun Belt for now."), EventChoice(id = "r_base", text = "Rally the base: maximize rural and evangelical turnout.", side = CandidateId.REP, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.05, enthusiasm = 0.02), BlocDelta(blocId = BlocId.SENIORS, margin = 0.03), BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = -0.02)), momentum = 3.0), resultText = "The rallies are roaring, but the ceiling with the suburbs holds."), EventChoice(id = "r_suburbs", text = "Pitch the suburbs: soften the edges for college voters.", side = CandidateId.REP, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.05), BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = 0.04), BlocDelta(blocId = BlocId.NONCOLL