    GameEvent(id = "h20_unrest", title = "Unrest in Kenosha", prompt = "After the police shooting of Jacob Blake, protests and some rioting break out in Kenosha, Wisconsin. The split-screen of marchers and burning storefronts runs on every channel in a state you have to win. Your move.", subject = "both", trigger = EventTrigger.Scheduled(turn = 1), choices = listOf(EventChoice(id = "d_tightrope", text = "Condemn the violence and back reform: walk the tightrope.", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.05), BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = 0.04), BlocDelta(blocId = BlocId.BLACK, margin = -0.02)), momentum = 2.0, narrative = 3.0), resultText = "The balance holds with the middle, but some of your base feels triangulated."), EventChoice(id = "d_justice", text = "Stand with the protesters and make it about justice.", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.BLACK, margin = 0.06, enthusiasm = 0.03), BlocDelta(blocId = BlocId.YOUTH, margin = 0.05), BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = -0.05), BlocDelta(blocId = BlocId.SENIORS, margin = -0.03)), momentum = 1.0, narrative = -3.0), resultText = "Your base is electrified, but the law-and-order ad writes itself for the other side."), EventChoice(id = "r_lawandorder", text = "Law and order: send in the feds and run the ad.", side = CandidateId.REP, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.06), BlocDelta(blocId = BlocId.SENIORS, margin = 0.04), BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = -0.05)), salienceDeltas = mapOf("law_and_order" to 0.06), momentum = 3.0, narrative = -2.0), resultText = "The base roars approval, and suburban women recoil from the heavy hand."), EventChoice(id = "r_calm", text = "Call for calm and unity: turn the temperature down.", side = CandidateId.REP, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.04), BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = 0.03), BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = -0.03)), momentum = 1.0, narrative = 3.0), resultText = "The grace note reassures the suburbs, but your base wanted a fighter.")), oncePerGame = true),
    GameEvent(id = "h20_covid", title = "Trump Hospitalized with COVID", prompt = "Cases surge as the weather turns, and Trump himself tests positive and is flown to Walter Reed. The pandemic is the only story for a week. How do you handle it?", subject = "both", trigger = EventTrigger.Scheduled(turn = 2), choices = listOf(EventChoice(id = "d_science", text = "Lead on masks and science: model the responsible path.", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.SENIORS, margin = 0.06), BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.05), BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = 0.04), BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = -0.02)), salienceDeltas = mapOf("covid_response" to 0.06), momentum = 4.0, narrative = 5.0), resultText = "Competence radiates. Seniors break your way, and the 'fear-monger' attack lands with rural voters."), EventChoice(id = "d_restraint", text = "Show restraint and empathy: don't politicize his illness.", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.04), BlocDelta(blocId = BlocId.SENIORS, margin = 0.03)), momentum = 2.0, narrative = 4.0), resultText = "The high road plays well, but you leave the sharpest contrast on the table."), EventChoice(id = "r_strength", text = "Project strength: back on the trail, downplay the risk.", side = CandidateId.REP, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.06, enthusiasm = 0.03), BlocDelta(blocId = BlocId.SENIORS, margin = -0.04), BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = -0.04)), salienceDeltas = mapOf("covid_response" to -0.04), momentum = 3.0, narrative = -3.0), resultText = "The base loves the defiance, but seniors and the suburbs are alarmed."), EventChoice(id = "r_vaccine", text = "Pivot to a vaccine and a reopening message.", side = CandidateId.REP, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.SENIORS, margin = 0.04), BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.03), BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.02)), salienceDeltas = mapOf("economy" to 0.04), momentum = 2.0, narrative = 1.0), resultText = "A forward-looking pitch steadies the seniors, though it doesn't fire up the rallies.")), oncePerGame = true),
    GameEvent(id = "h20_scotus", title = "Ruth Bader Ginsburg Dies", prompt = "Justice Ruth Bader Ginsburg dies six weeks out, and the Supreme Court is suddenly the center of the race, with a fight over filling the seat before Election Day. Small-dollar money floods both sides overnight.", subject = "both", trigger = EventTrigger.Scheduled(turn = 3), choices = listOf(EventChoice(id = "d_healthcare", text = "Make it about healthcare: the ACA is on the line.", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.05), BlocDelta(blocId = BlocId.SENIORS, margin = 0.05), BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = 0.04)), salienceDeltas = mapOf("healthcare" to 0.06), momentum = 4.0, cash = 15000000.0, narrative = 3.0), resultText = "You sidestep the court-packing trap and fight on healthcare. Your strongest ground."), EventChoice(id = "d_pack", text = "Cry foul on the process and hint at expanding the Court.", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.YOUTH, margin = 0.05), BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = 0.03), BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = -0.04), BlocDelta(blocId = BlocId.SENIORS, margin = -0.03)), momentum = 1.0, cash = 18000000.0, narrative = -3.0), resultText = "The base is fired up and the money pours in, but 'pack the court' spooks the middle."), EventChoice(id = "r_ram", text = "Ram the nominee through: energize evangelicals.", side = CandidateId.REP, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.06, enthusiasm = 0.03), BlocDelta(blocId = BlocId.SENIORS, margin = 0.04), BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = -0.04)), salienceDeltas = mapOf("abortion" to 0.05), momentum = 3.0, cash = 18000000.0, narrative = -1.0), resultText = "The base turns out in force, and suburban women grow uneasy about the rush."), EventChoice(id = "r_economy", text = "P