    GameEvent(id = "h20_debate1", title = "First Debate (Cleveland)", prompt = "Ninety minutes of chaos and interruptions in Cleveland. \"Will you shut up, man?\" Biden and Trump talk over each other for the most-anticipated debate of the race. How do you carry yourself on the biggest stage?", subject = "both", trigger = EventTrigger.Scheduled(turn = 4), choices = listOf(EventChoice(id = "calm_presidential", text = "Stay calm and presidential: talk to the camera, not your opponent.", effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.06), BlocDelta(blocId = BlocId.SENIORS, margin = 0.05), BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = 0.04), BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = -0.01)), momentum = 7.0, narrative = 9.0), resultText = "You refuse the bait. The split-screen does the work: steady and reassuring."), EventChoice(id = "aggressive", text = "Interrupt and dominate: never yield the floor.", effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.05, enthusiasm = 0.02), BlocDelta(blocId = BlocId.YOUTH, margin = 0.02), BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = -0.05), BlocDelta(blocId = BlocId.SENIORS, margin = -0.03)), momentum = 4.0, narrative = -6.0), resultText = "You fire up the base, but the constant crosstalk reads as a mess at home."), EventChoice(id = "wonk", text = "Bury them in policy detail and dare them to keep up.", requires = TraitRequirement(trait = "policyKnowledge", min = 70.0), effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = 0.06), BlocDelta(blocId = BlocId.SENIORS, margin = 0.02)), salienceDeltas = mapOf("healthcare" to 0.03), momentum = 5.0, narrative = 4.0), resultText = "Command of the substance wins the fact-checkers. A touch clinical for some.")), isDebate = true, oncePerGame = true),
    GameEvent(id = "h20_vpdebate", title = "Vice-Presidential Debate (Salt Lake City)", prompt = "A calmer undercard in Salt Lake City: two running mates behind plexiglass, and a fly that lands on one of them long enough to steal the night. No knockout to be had, but a steady showing reassures, and a sharp one bleeds.", subject = "both", trigger = EventTrigger.Scheduled(turn = 5), choices = listOf(EventChoice(id = "disciplined", text = "Stay disciplined and reassuring.", effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.04), BlocDelta(blocId = BlocId.SENIORS, margin = 0.04)), momentum = 4.0, narrative = 4.0), resultText = "Your number two looks ready for the job. The grown-up tone reassures the middle."), EventChoice(id = "offense", text = "Go on offense and draw blood.", effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.03, enthusiasm = 0.02), BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = -0.03)), momentum = 2.0, narrative = -2.0), resultText = "The base enjoys the hits, but the aggression turns off the undecideds watching.")), isDebate = true, oncePerGame = true),
    GameEvent(id = "h20_jobs", title = "A Surprise Jobs Report", prompt = "The monthly jobs numbers blow past expectations. A rare bright spot in a dark year. Both campaigns scramble to spin it.", subject = "both", trigger = EventTrigger.Scheduled(turn = 6), choices = listOf(EventChoice(id = "r_credit", text = "Take the credit: the recovery is roaring back.", side = CandidateId.REP, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.05), BlocDelta(blocId = BlocId.SENIORS, margin = 0.03), BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.02)), salienceDeltas = mapOf("economy" to 0.06), momentum = 4.0, narrative = 3.0), resultText = "The comeback story lands, though it invites the question of how deep the hole was."), EventChoice(id = "r_reopen", text = "Pair it with a full reopening message.", side = CandidateId.REP, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.04), BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = 0.02)), salienceDeltas = mapOf("economy" to 0.05), momentum = 3.0, narrative = 2.0), resultText = "You ride the optimism, and dare the other side to root against the recovery."), EventChoice(id = "d_hole", text = "Remind them it's still a deep hole: millions are out of work.", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.04), BlocDelta(blocId = BlocId.SENIORS, margin = 0.03), BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.03)), salienceDeltas = mapOf("economy" to 0.04), momentum = 3.0, narrative = 2.0), resultText = "You contest the economy on his turf: risky, but the pain is real for many."), EventChoice(id = "d_pivot", text = "Pivot back to the virus and healthcare.", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.04), BlocDelta(blocId = BlocId.SENIORS, margin = 0.04)), salienceDeltas = mapOf("healthcare