    GameEvent(id = "h20_finaldebate", title = "Final Debate (Nashville)", prompt = "The last Biden-Trump debate in Nashville, with mute buttons this time to keep it civil. The undecideds who are left are watching for one reason to break. Make your closing case.", subject = "both", trigger = EventTrigger.Scheduled(turn = 7), choices = listOf(EventChoice(id = "unity", text = "Close on unity and turning the page.", effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.05), BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = 0.04)), momentum = 6.0, narrative = 7.0), resultText = "You end on a high note. The closing montage practically writes itself."), EventChoice(id = "contrast", text = "Draw a hard contrast: make it a choice, not a referendum.", effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.05), BlocDelta(blocId = BlocId.SENIORS, margin = 0.03), BlocDelta(blocId = BlocId.YOUTH, margin = -0.02)), momentum = 5.0, narrative = 0.0), resultText = "You sharpen the stakes: your base is energized, a few swing voters tire of it.")), isDebate = true, oncePerGame = true)
)

