    GameEvent(id = "h16_deplorables", title = "The 'Basket of Deplorables'", prompt = "Hillary Clinton's line from a closed-door fundraiser, that half of Trump's supporters dropped into a \"basket of deplorables\", leaks and is everywhere by morning.", subject = "dem", trigger = EventTrigger.Scheduled(turn = 0), choices = listOf(EventChoice(id = "d_walk", text = "Walk it back: say you regret the generalization.", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.04), BlocDelta(blocId = BlocId.SENIORS, margin = 0.03), BlocDelta(blocId = BlocId.YOUTH, margin = -0.02)), momentum = 1.0, narrative = 3.0), resultText = "The cleanup holds with the middle, though the base wishes you'd stood your ground."), EventChoice(id = "d_double", text = "Stand by the sentiment: call out the bigotry by name.", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = 0.04), BlocDelta(blocId = BlocId.YOUTH, margin = 0.04), BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = -0.06)), momentum = 2.0, narrative = -3.0), resultText = "The base cheers, but the clip becomes the other side's favorite recruiting tool."), EventChoice(id = "r_grievance", text = "Make it about the insult: 'they look down on you.'", side = CandidateId.REP, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.06, enthusiasm = 0.03), BlocDelta(blocId = BlocId.SENIORS, margin = 0.03), BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = -0.01)), momentum = 4.0, narrative = 1.0), resultText = "The grievance lands hard with working-class voters who feel sneered at."), EventChoice(id = "r_presidential", text = "Stay above it and look presidential for once.", side = CandidateId.REP, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.04), BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = 0.03), BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = -0.02)), momentum = 1.0, narrative = 3.0), resultText = "A rare disciplined day reassures wary suburbanites, and bores the base.")), oncePerGame = true),
    GameEvent(id = "h16_health", title = "A Stumble at a 9/11 Memorial", prompt = "Hillary Clinton buckles and is helped into a van leaving the 9/11 memorial, caught on a bystander's phone. A pneumonia diagnosis the campaign had sat on sets off a stamina frenzy.", subject = "dem", trigger = EventTrigger.Scheduled(turn = 1), choices = listOf(EventChoice(id = "d_records", text = "Release detailed medical records and get back out fast.", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.SENIORS, margin = 0.05), BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.03)), momentum = 4.0, narrative = 5.0), resultText = "Transparency defuses it. A brisk rally swing puts the stamina story to bed."), EventChoice(id = "d_powerthrough", text = "Power through: pack the schedule, say little.", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.02), BlocDelta(blocId = BlocId.SENIORS, margin = -0.04)), momentum = 2.0, narrative = -3.0), resultText = "You project toughness, but the silence lets the speculation run another week."), EventChoice(id = "r_amplify", text = "Amplify the stamina question: 'is she up to it?'", side = CandidateId.REP, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.04), BlocDelta(blocId = BlocId.SENIORS, margin = 0.04), BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = -0.03)), momentum = 3.0, narrative = -2.0), resultText = "The doubts spread, though piling on a sick opponent costs you with women."), EventChoice(id = "r_restraint", text = "Show uncharacteristic restraint and wish her well.", side = CandidateId.REP, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.04), BlocDelta(blocId = BlocId.SENIORS, margin = 0.03)), momentum = 1.0, narrative = 3.0), resultText = "Magnanimity surprises the press and softens your edges. For a day.")), oncePerGame = true),
    GameEvent(id = "h16_debate1", title = "First Debate (Hofstra)", prompt = "Clinton vs. Trump at Hofstra: the most-watched debate in history. One of you is over-prepared, one is winging it. Ninety minutes to define the race.", subject = "both", trigger = EventTrigger.Scheduled(turn = 2), choices = listOf(EventChoice(id = "bait", text = "Set traps: bait your opponent into an unforced error.", effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = 0.05), BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.05), BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = -0.02)), momentum = 6.0, narrative = 8.0), resultText = "The traps spring. The post-debate clips run against your opponent for days."), EventChoice(id = "punch", text = "Throw haymakers: never concede a point.", effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.05, enthusiasm = 0.02), BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = -0.04)), momentum = 3.0, narrative = -4.0), resultText = "The base is thrilled; suburban viewers are exhausted.")), isDebate = true, oncePerGame = true),
    GameEvent(id = "h16_tape", title = "An 'Access Hollywood' Bombshell", prompt = "A decade-old hot-mic recording of the Republican nominee surfaces a month out, and it is ugly. Down-ballot allies are running for the exits. This is the hinge of the campaign.", subject = "rep", trigger = EventTrigger.Scheduled(turn = 4), choices = listOf(EventChoice(id = "r_apologize", text = "Apologize, contain the damage, and counterpunch.", side = CandidateId.REP, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.03, enthusiasm = 0.02), BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = -0.06), BlocDelta(blocId = BlocId.SENIORS, margin = -0.03)), momentum = -4.0, narrative = -6.0), resultText = "The base sticks, but the bleeding with women and seniors doesn't fully stop."), EventChoice(id = "r_dismiss", text = "Dismiss it as 'locker-room talk' and change the subject.", side = CandidateId.REP, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.02), BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = -0.08)), momentum = -5.0, narrative = -8.0), resultText = "The framing collapses on contact. The story runs for two solid weeks."), EventChoice(id = "d_capitalize", text = "Capitalize: cut a contrast ad tonight and let it breathe.", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.07), BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = 0.05), BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = -0.01)), momentum = 8.0, narrative = 9.0), resultText = "You let the tape do the talking. Suburban women break hard your way."), EventChoice(id = "d_aboveit", text = "Stay above it: keep your own closing message.", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.03), BlocDelta(blocId = BlocId.SENIORS, margin = 0.02)), momentum = 3.0, narrative = 4.0), resultText = "Di