    GameEvent(id = "h04_swiftboat", title = "The Swift Boat Attacks", prompt = "A group calling itself Swift Boat Veterans for Truth runs ads attacking Kerry's Vietnam record and medals. Disputed, but everywhere. The story refuses to die for two weeks.", subject = "dem", trigger = EventTrigger.Scheduled(turn = 1), choices = listOf(EventChoice(id = "d_fightback", text = "Hit back hard: call the smears what they are.", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.SENIORS, margin = 0.04), BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = 0.04), BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = -0.02)), momentum = 3.0, narrative = 2.0), resultText = "You blunt the worst of it, but every day spent defending is a day off your message."), EventChoice(id = "d_ignore", text = "Stay above it: refuse to dignify the smear.", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.03), BlocDelta(blocId = BlocId.SENIORS, margin = -0.04), BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = -0.03)), momentum = -2.0, narrative = -4.0), resultText = "The high road lets the attack metastasize. The doubts harden."), EventChoice(id = "r_letitride", text = "Let the outside groups do the work: stay clean.", side = CandidateId.REP, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.05), BlocDelta(blocId = BlocId.SENIORS, margin = 0.03), BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = -0.01)), momentum = 4.0, narrative = 0.0), resultText = "Plausible deniability holds while the attack does real damage."), EventChoice(id = "r_disavow", text = "Disavow the ads to keep your hands clean.", side = CandidateId.REP, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.04), BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = 0.03), BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = -0.03)), momentum = 1.0, narrative = 3.0), resultText = "The high road impresses the suburbs, and the base grumbles you gave up a weapon.")), oncePerGame = true),
    GameEvent(id = "h04_debate1", title = "First Debate (Coral Gables)", prompt = "Bush and Kerry in Coral Gables: a foreign-policy debate with Iraq front and center. Kerry is crisp and precise; Bush risks looking impatient behind the podium. Command the stage.", subject = "both", trigger = EventTrigger.Scheduled(turn = 2), choices = listOf(EventChoice(id = "command", text = "Command the substance: a precise case on the war.", requires = TraitRequirement(trait = "debatePrep", min = 70.0), effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = 0.05), BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.05), BlocDelta(blocId = BlocId.SENIORS, margin = 0.03)), momentum = 6.0, narrative = 7.0), resultText = "You look sharp and in command. The instant polls give you the night."), EventChoice(id = "resolve", text = "Project steady resolve: no second-guessing in wartime.", effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.05), BlocDelta(blocId = BlocId.SENIORS, margin = 0.04), BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = -0.02)), momentum = 4.0, narrative = 2.0), resultText = "Steadiness reassures the base, but a few exchanges read as stubborn.")), isDebate = true, oncePerGame = true),
    GameEvent(id = "h04_iraq", title = "The 'Wrong War' Question", prompt = "Casualties mount and the rationale for the war frays. The campaign becomes a referendum on whether it was a mistake, and whether you can say so.", subject = "both", trigger = EventTrigger.Scheduled(turn = 4), choices = listOf(EventChoice(id = "d_critique", text = "Call it the wrong war at the wrong time.", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.YOUTH, margin = 0.05), BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = 0.04), BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = -0.03), BlocDelta(blocId = BlocId.SENIORS, margin = -0.02)), salienceDeltas = mapOf("law_and_order" to 0.04), momentum = 3.0, narrative = 1.0), resultText = "The base is energized, but 'wavering in wartime' is exactly the attack you feared."), EventChoice(id = "d_competence", text = "Make it about competence: the peace was botched.", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.05), BlocDelta(blocId = BlocId.SENIORS, margin = 0.03), BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = 0.03)), momentum = 4.0, narrative = 3.0), resultText = "Attacking the execution, not the cause, threads the needle with the middle."), EventChoice(id = "r_resolve", text = "Stay the course: resolve over second-guessing.", side = CandidateId.REP, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.05, enthusiasm = 0.02), BlocDelta(blocId = BlocId.SENIORS, margin = 0.03), BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = -0.03)), salienceDeltas = mapOf("law_and_order" to 0.04), momentum = 4.0, narrative = 0.0), resultText = "The unwavering line rallies the base, and the war-weary suburbs wince."), EventChoice(id = "r_flipflop", text = "Paint the opponent as a flip-flopper.", side = CandidateId.REP, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.04), BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.02), BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = -0.01)), momentum = 4.0, narrative = 2.0), resultText = "The 'for it before he was against it' frame sticks like glue.")), oncePerGame = true),
    GameEvent(id = "h04_memo", title = "Rathergate: The Forged Memos", prompt = "CBS's 60 Minutes and Dan Rather air an exposé on Bush's National Guard service, then the documents are exposed as likely forgeries. The story is now about the media, not the record.", subject = "rep", trigger = EventTrigger.Scheduled(turn = 5), choices = listOf(EventChoice(id = "r_letit", text = "Let it implode: sit back and watch the press squirm.", side = CandidateId.REP, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.05), BlocDelta(blocId = BlocId.SENIORS, margin = 0.03), BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = -0.01)), momentum = 4.0, narrative = 3.0), resultText = "The media's self-inflicted wound becomes a gift. The base feels vindicated."), EventChoice(id = "r_grievance", text = "Run on media bias: make grievance the message.", side = CandidateId.REP, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.06, enthusiasm = 0.03), BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = -0.02)), momentum = 4.0, narrative = -1.0), resultText = "The base is electrified, though dwelling on grievance leaves the suburbs cold."), EventChoice(id = "d_drop", text = "Drop it entirely: pivot back to jobs and Iraq.", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.04), BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.03)), salienceDeltas = mapOf("economy" to 0.04), momentum = 3.0, narrative = 3.0), resultText = "You cut your losses and change the subject to firmer ground."), EventChoice(id = "d_press", text = "Keep pressing the underlying question.", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.YOUTH, margin = 0.03), BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = 0.02), BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = -0.03)), momentum = 0.0, narrative = -3.0), resultText = "You keep poking, and end up tangled in the discredited story yourself.")), oncePerGame = true),
    GameEvent(id = "h04_octobersurprise", title = "The Bin Laden Tape", prompt = "Days before the vote, a new Osama bin Laden video airs, dragging the war on terror and national security back to the center of the race.", subject = "both", trigger = EventTrigger.Scheduled(turn = 7), choices = listOf(EventChoice(id = "r_strength", text = "Project strength: remind them who keeps you safe.", side = CandidateId.REP, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.05), BlocDelta(blocId = BlocId.SENIORS, margin = 0.05), BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.02)), salienceDeltas = mapOf("law_and_order" to 0.06), momentum = 5.0, narrative = 3.0), resultText = "Security surges back to the top of the ballot: your strongest closing ground."), EventChoice(id = "r_steady", text = "Stay calm and statesmanlike: don't overplay it.", side = CandidateId.REP, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.04), BlocDelta(blocId = BlocId.SENIORS, margin = 0.04)), momentum = 3.0, narrative = 4.0), resultText = "Restraint reads as presidential, and quietly reminds everyone of the stakes."), EventChoice(id = "d_caution", text = "Warn against fear and a forever war.", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.YOUTH, margin = 0.05), BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = 0.03), BlocDelta(blocId = BlocId.SENIORS, margin = -0.03), BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = -0.02)), momentum = 2.0, narrative = -2.0), resultText = "The base nods, but a security scare is the worst week to question toughness."), EventChoice(id = "d_steady", text = "Match the resolve: you'll hunt them down too.", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.SENIORS, margin = 0.04), BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.03), BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.02)), salienceDeltas = mapOf("law_and_order" to 0.03), momentum = 3.0, narrative = 2.0), resultText = "You refuse to be out-toughed: neutralizing the surprise as best you can.")), oncePerGame = true)
)

val HIST_2000: List<GameEvent> = listOf(
    GameEvent(id = "h00_convention", title = "Stepping Out of Clinton's Shadow", prompt = "Peace, prosperity, and a budget surplus, but Al Gore must decide how close to stand to Bill Clinton, popular yet shadowed by impeachment, while George W. Bush runs to \"restore honor and dignity.\" Set your stance.", subject = "both", trigger = EventTrigger.Scheduled(turn = 0), choices = listOf(EventChoice(id = "d_ownman", text = "Be your own man: run a populist 'people vs. powerful' pitch.", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.05), BlocDelta(blocId = BlocId.YOUTH, margin = 0.03), BlocDelta(blocId = BlocId.SENIORS, margin = 0.02)), salienceDeltas = mapOf("economy" to 0.04), momentum = 4.0, narrative = 3.0), resultText = "The fighting-populist framing finds its own voice, and walks away from a good economy."), EventChoice(id = "d_continuity", text = "Run on continuity: don't mess with prosperity.", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.SENIORS, margin = 0.05), BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = 0.04), BlocDelta(blocId = BlocId.YOUTH, margin = -0.02)), salienceDeltas = mapOf("economy" to 0.05), momentum = 4.0, narrative = 4.0), resultText = "The steady-as-she-goes case reassures, but ties you to the baggage too."), EventChoice(id = "r_change", text = "Run as a fresh start: restore honor and dignity.", side = CandidateId.REP, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.04), BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.04), BlocDelta(blocId = BlocId.SENIORS, margin = -0.02)), momentum = 4.0, narrative = 3.0), resultText = "The change-of-tone pitch excites voters bored of the incumbents."), EventChoice(id = "r_compassion", text = "Lead with 'compassionate conservatism' and education.", side = CandidateId.REP, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.05), BlocDelta(blocId = BlocId.HISPANIC, margin = 0.04), BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = -0.02)), salienceDeltas = mapOf("healthcare" to 0.03), momentum = 3.0, narrative = 3.0), resultText = "The softer brand reaches suburban and Latino voters, at some cost to base intensity.")), oncePerGame = true),
    GameEvent(id = "h00_debate1", title = "First Debate (Boston)", prompt = "Gore and Bush in Boston. Gore risks the audible sighs and eye-rolls that read as condescending; Bush risks looking out of his depth. Mannerisms will matter as much as substance.", subject = "both", trigger = EventTrigger.Scheduled(turn = 2), choices = listOf(EventChoice(id = "command", text = "Command the substance: bury them in policy.", requires = TraitRequirement(trait = "policyKnowledge", min = 70.0), effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = 0.05), BlocDelta(blocId = BlocId.SENIORS, margin = 0.03), BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = -0.03)), momentum = 4.0, narrative = 2.0), resultText = "You win on points, but the sighing and eye-rolling become the story."), EventChoice(id = "likeable", text = "Play it warm and likeable: connect, don't lecture.", effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.05), BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.04)), momentum = 5.0, narrative = 5.0), resultText = "Affable beats encyclopedic. The 'who'd you rather have a beer with' crowd warms to you.")), isDebate = true, oncePerGame = true),
    GameEvent(id = "h00_vpdebate", title = "A Cordial VP Debate", prompt = "An unusually civil, substantive undercard. No fireworks: just two running mates making the case. Whose ticket does it help?", subject = "both", trigger = EventTrigger.Scheduled(turn = 3), choices = listOf(EventChoice(id = "gravitas", text = "Sell experience and a steady hand.", effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.SENIORS, margin = 0.04), BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = 0.03)), momentum = 3.0, narrative = 3.0), resultText = "The grown-up tone reassures voters worried about the top of the ticket."), EventChoice(id = "future", text = "Sell freshness and the next generation.", effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.YOUTH, margin = 0.04), BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.03)), momentum = 3.0, narrative = 2.0), resultText = "A forward-looking pitch nudges younger and suburban voters your way.")), isDebate = true, oncePerGame = true),
    GameEvent(id = "h00_townhall", title = "The Town-Hall Debate", prompt = "Gore and Bush in a town-hall format with undecided voters in the room. Body language is everything; when Gore strides over and looms at Bush's shoulder, one awkward move can define you.", subject = "both", trigger = EventTrigger.Scheduled(turn = 5), choices = listOf(EventChoice(id = "connect", text = "Work the room: empathy and eye contact.", effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.05), BlocDelta(blocId = BlocId.BLACK, margin = 0.03)), momentum = 4.0, narrative = 4.0), resultText = "You connect with the room. The reaction shots all break your way."), EventChoice(id = "loom", text = "Assert dominance: crowd the stage and your opponent.", effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.03), BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = -0.05)), momentum = 1.0, narrative = -4.0), resultText = "The move reads as aggressive and odd. The clip loops for days.")), isDebate = true, oncePerGame = true),
    GameEvent(id = "h00_ads", title = "The 'RATS' Ad", prompt = "A Bush attack ad is caught flashing the word \"RATS\" for a single frame as \"BUREAUCRATS\" scrolls past. A thirtieth of a second of alleged subliminal messaging. It's silly, and it's leading every newscast.", subject = "rep", trigger = EventTrigger.Scheduled(turn = 6), choices = listOf(EventChoice(id = "r_laugh", text = "Laugh it off and pull the ad.", side = CandidateId.REP, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = 0.03), BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.02)), momentum = 1.0, narrative = 2.0), resultText = "A light touch makes the story evaporate by the weekend."), EventChoice(id = "r_deny", text = "Deny everything and keep the ad running.", side = CandidateId.REP, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.02), BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = -0.03)), momentum = 0.0, narrative = -3.0), resultText = "The denial keeps the silly story alive for an extra week of bad coverage."), EventChoice(id = "d_pounce", text = "Pounce: call it a dirty trick.", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = 0.03), BlocDelta(blocId = BlocId.YOUTH, margin = 0.02), BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = -0.02)), momentum = 1.0, narrative = -1.0), resultText = "You score a small point, but risk looking like you're sweating the small stuff."), EventChoice(id = "d_ignore", text = "Stay focused on prescription drugs and Social Security.", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.SENIORS, margin = 0.04), BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.02)), salienceDeltas = mapOf("healthcare" to 0.04), momentum = 2.0, narrative = 2.0), resultText = "Discipline on the issues seniors care about beats chasing a gimmick.")), oncePerGame = true),
    GameEvent(id = "h00_dui", title = "Bush's DUI Surfaces", prompt = "Days before the vote, a 1976 drunk-driving arrest of George W. Bush surfaces and dominates the final weekend. It's decades-old news, but the timing is brutal.", subject = "rep", trigger = EventTrigger.Scheduled(turn = 7), choices = listOf(EventChoice(id = "r_honest", text = "Get ahead of it: own it, be honest, move on.", side = CandidateId.REP, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.04), BlocDelta(blocId = BlocId.SENIORS, margin = 0.03)), momentum = 3.0, narrative = 4.0), resultText = "Candor blunts the hit. Voters respect the straight answer in the final hours."), EventChoice(id = "r_deflect", text = "Cry dirty trick and blame the timing.", side = CandidateId.REP, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.03, enthusiasm = 0.02), BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = -0.03)), momentum = 2.0, narrative = -2.0), resultText = "The base rallies to your defense, but the deflection keeps the story alive."), EventChoice(id = "d_exploit", text = "Exploit it: quietly question their character to the last.", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.04), BlocDelta(blocId = BlocId.SENIORS, margin = 0.03), BlocDelta(blocId = BlocId.YOUTH, margin = -0.02)), momentum = 3.0, narrative = -1.0), resultText = "The character hit lands with some, but late mud splashes back on you, too."), EventChoice(id = "d_positive", text = "Resist the temptation: close on your own positive message.", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.04), BlocDelta(blocId = BlocId.SENIORS, margin = 0.03)), momentum = 3.0, narrative = 3.0), resultText = "Staying positive in the final hours keeps the high ground, and lets it speak for itself.")), oncePerGame = true)
