val HIST_1996: List<GameEvent> = listOf(
    GameEvent(id = "h96_resign", title = "Citizen Dole, Incumbent of the Center", prompt = "Bob Dole resigns his Senate seat and the majority leadership, \"nowhere to go but the White House or home\", while Bill Clinton plants his flag in the middle: \"the era of big government is over.\" Two opening bets. Place yours.", subject = "both", trigger = EventTrigger.Scheduled(turn = 0), choices = listOf(EventChoice(id = "r_allin", text = "Leave the Senate behind: run as Citizen Dole, all in.", side = CandidateId.REP, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.04, enthusiasm = 0.02), BlocDelta(blocId = BlocId.SENIORS, margin = 0.03), BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = -0.02)), momentum = 4.0, narrative = 3.0), resultText = "The gamble reads as conviction, though you just gave up the only stage where you outrank a president."), EventChoice(id = "r_record", text = "Keep one foot in Washington: run on the resume and the record.", side = CandidateId.REP, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.SENIORS, margin = 0.04), BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = 0.03), BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = -0.02)), momentum = 2.0, narrative = 1.0), resultText = "The steady case lands with older voters, but 'Senator' is exactly the brand you needed to shed."), EventChoice(id = "d_triangulate", text = "Claim the center: small government, school uniforms, V-chips.", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.05), BlocDelta(blocId = BlocId.SENIORS, margin = 0.04), BlocDelta(blocId = BlocId.YOUTH, margin = -0.03), BlocDelta(blocId = BlocId.BLACK, margin = -0.02)), momentum = 4.0, narrative = 4.0), resultText = "Triangulation leaves your opponent almost nothing to run on, and your own base muttering about what you stand for."), EventChoice(id = "d_base", text = "Rally the coalition: Medicare, education, the environment.", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.BLACK, margin = 0.04, enthusiasm = 0.02), BlocDelta(blocId = BlocId.YOUTH, margin = 0.04), BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = -0.02)), momentum = 3.0, narrative = 2.0), resultText = "The old religion fires up the faithful, and reopens the 'liberal' lane you'd sealed off.")), oncePerGame = true),
    GameEvent(id = "h96_shutdown", title = "The Shutdown Hangover", prompt = "The government-shutdown wars of the winter still hang over the race. Voters blamed Newt Gingrich and the new Congress, and Dole was the man standing next to him. The 'Dole-Gingrich' hyphen is already in Democratic ad scripts.", subject = "rep", trigger = EventTrigger.Scheduled(turn = 1), choices = listOf(EventChoice(id = "r_distance", text = "Break with Gingrich: you're the one who reopened the government.", side = CandidateId.REP, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.04), BlocDelta(blocId = BlocId.SENIORS, margin = 0.03), BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = -0.03)), momentum = 2.0, narrative = 3.0), resultText = "The distance helps with the middle, and the revolutionaries in your own party call it a surrender."), EventChoice(id = "r_defend", text = "Defend the fight: a balanced budget required hard medicine.", side = CandidateId.REP, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.04, enthusiasm = 0.02), BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = -0.03), BlocDelta(blocId = BlocId.SENIORS, margin = -0.03)), salienceDeltas = mapOf("taxes" to 0.04), momentum = 1.0, narrative = -2.0), resultText = "The base appreciates the spine, and every senior who missed a park visit remembers whose shutdown it was."), EventChoice(id = "d_hyphen", text = "Weld the hyphen: 'Dole-Gingrich' in every ad, every night.", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.SENIORS, margin = 0.05), BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.03), BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = -0.02)), momentum = 4.0, narrative = -2.0), resultText = "The hyphen sticks like tar. The relentless negativity wears a little thin in the suburbs."), EventChoice(id = "d_above", text = "Take the win quietly: talk about the future, not the fight.", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.04), BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = 0.03), BlocDelta(blocId = BlocId.SENIORS, margin = -0.02)), momentum = 2.0, narrative = 3.0), resultText = "Magnanimity polls well, though seniors wish you'd kept the Medicare knife twisting.")), oncePerGame = true),
    GameEvent(id = "h96_welfare", title = "Signing Welfare Reform", prompt = "Congress sends Clinton a welfare-reform bill he promised in 1992 and vetoed twice since. Sign it and 'end welfare as we know it', enraging half his own party, or veto again in an election year.", subject = "dem", trigger = EventTrigger.Scheduled(turn = 2), choices = listOf(EventChoice(id = "d_sign", text = "Sign it: keep the promise, own the center.", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.05), BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.04), BlocDelta(blocId = BlocId.BLACK, margin = -0.04), BlocDelta(blocId = BlocId.YOUTH, margin = -0.03)), salienceDeltas = mapOf("economy" to 0.03), momentum = 4.0, narrative = 2.0), resultText = "The signature takes the issue off the table for good, and senior staff resign in protest on your way out of the Rose Garden."), EventChoice(id = "d_veto", text = "Veto a third time: defend the safety net, whatever it costs.", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.BLACK, margin = 0.05, enthusiasm = 0.02), BlocDelta(blocId = BlocId.YOUTH, margin = 0.04), BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = -0.04), BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = -0.03)), momentum = 1.0, narrative = -2.0), resultText = "The base exhales, and the 'same old liberal' ad practically edits itself."), EventChoice(id = "r_credit", text = "Claim the credit: Congress wrote it, he just held the pen.", side = CandidateId.REP, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.04), BlocDelta(blocId = BlocId.SENIORS, margin = 0.03), BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = -0.01)), momentum = 2.0, narrative = 0.0), resultText = "A fair point that never quite lands: it's hard to out-sign the man with the signature."), EventChoice(id = "r_conversion", text = "Call it an election-year conversion: he vetoed it twice.", side = CandidateId.REP, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = 0.03), BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.02), BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = -0.02)), momentum = 1.0, narrative = -1.0), resultText = "The flip-flop charge is true and tidy, and voters mostly just pocket the reform.")), oncePerGame = true),
    GameEvent(id = "h96_morris", title = "The Dick Morris Scandal", prompt = "Convention week. The tabloids catch Dick Morris, architect of the whole triangulation strategy, with a call girl who listened in on calls to the president. The story breaks the morning of the acceptance speech.", subject = "dem", trigger = EventTrigger.Scheduled(turn = 4), choices = listOf(EventChoice(id = "d_cut", text = "Cut him loose within the hour: the speech goes on.", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.04), BlocDelta(blocId = BlocId.SENIORS, margin = 0.03)), momentum = 1.0, narrative = 2.0), resultText = "The swift execution contains the story to a single cycle, and the campaign loses its chief strategist mid-convention."), EventChoice(id = "d_loyal", text = "Stand by him: refuse to feed the tabloids.", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.02), BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = -0.05), BlocDelta(blocId = BlocId.SENIORS, margin = -0.03)), momentum = -2.0, narrative = -5.0), resultText = "Loyalty is admirable and unsurvivable. The values story tramples your convention for a week."), EventChoice(id = "r_values", text = "Make it a values contrast: 'look who the White House keeps close.'", side = CandidateId.REP, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.04, enthusiasm = 0.02), BlocDelta(blocId = BlocId.SENIORS, margin = 0.03), BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = -0.03)), momentum = 3.0, narrative = -2.0), resultText = "The base enjoys the sermon, and wading into tabloid mud splashes on the preacher too."), EventChoice(id = "r_taxcut", text = "Leave the tabloids to it: sell the 15 percent tax cut.", side = CandidateId.REP, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.03), BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = 0.02)), salienceDeltas = mapOf("taxes" to 0.04), momentum = 2.0, narrative = 2.0), resultText = "Discipline keeps you on your own message, and the scandal burns out without your fingerprints.")), oncePerGame = true),
    GameEvent(id = "h96_chico", title = "The Fall in Chico", prompt = "A railing gives way at a rally in Chico, California, and the 73-year-old Dole tumbles off the stage on live television. He's fine, but the age issue, and Clinton's 'bridge to the 21st century,' are suddenly the whole conversation.", subject = "rep", trigger = EventTrigger.Scheduled(turn = 5), choices = listOf(EventChoice(id = "r_humor", text = "Bounce up with a joke and outwork it: announce a 96-hour final marathon.", side = CandidateId.REP, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.SENIORS, margin = 0.04), BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.03), BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = -0.01)), momentum = 3.0, narrative = 3.0), resultText = "The quip and the punishing schedule blunt the story, at the price of a candidate running on fumes."), EventChoice(id = "r_bridge_past", text = "Lean into it: age is wisdom, a bridge to a better America of tried and true values.", side = CandidateId.REP, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.SENIORS, margin = 0.05), BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.03), BlocDelta(blocId = BlocId.YOUTH, margin = -0.04), BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = -0.02)), momentum = 2.0, narrative = -1.0), resultText = "The nostalgia warms your base, and hands the other side its 'bridge to the past' punchline gift-wrapped."), EventChoice(id = "d_bridge", text = "Answer with the bridge to the 21st century: future versus past, never mention the fall.", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.YOUTH, margin = 0.05), BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.04), BlocDelta(blocId = BlocId.SENIORS, margin = -0.03)), momentum = 4.0, narrative = 4.0), resultText = "The generational frame does the age work without your fingerprints, though seniors hear the subtext clearly."), EventChoice(id = "d_classy", text = "Order the campaign off it entirely: wish him well, no age jokes.", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.SENIORS, margin = 0.04), BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.03), BlocDelta(blocId = BlocId.YOUTH, margin = -0.02)), momentum = 2.0, narrative = 3.0), resultText = "The restraint reads as grace, and leaves your sharpest contrast unspoken.")), oncePerGame = true),
    GameEvent(id = "h96_debate", title = "The Hartford Debate", prompt = "Clinton and Dole in Hartford. Dole's advisers are begging him to go after the ethics file; Clinton's want him serene and presidential. Ninety minutes to move a race that's barely moved all fall.", subject = "both", trigger = EventTrigger.Scheduled(turn = 6), choices = listOf(EventChoice(id = "civil", text = "Keep it civil: reassure, don't wound.", effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.05), BlocDelta(blocId = BlocId.SENIORS, margin = 0.04), BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = -0.02)), momentum = 4.0, narrative = 5.0), resultText = "A gentleman's night. The middle is reassured; your war room wanted blood."), EventChoice(id = "ethics", text = "Go after ethics and character: Whitewater, the donors, the pardons talk.", effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.05, enthusiasm = 0.02), BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = -0.04)), momentum = 3.0, narrative = -3.0), resultText = "The base finally gets its fight, and the attack-dog clips play badly with everyone else."), EventChoice(id = "numbers", text = "Win on the numbers: the 15 percent cut versus the balanced budget.", requires = TraitRequirement(trait = "policyKnowledge", min = 70.0), effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = 0.05), BlocDelta(blocId = BlocId.SENIORS, margin = 0.03)), salienceDeltas = mapOf("taxes" to 0.04), momentum = 4.0, narrative = 3.0), resultText = "You out-arithmetic the other podium. Green-eyeshade voters nod; everyone else checks the score.")), isDebate = true, oncePerGame = true)
)

val HIST_1992: List<GameEvent> = listOf(
    GameEvent(id = "h92_lips", title = "'Read My Lips' Comes Due", prompt = "The 1988 convention pledge, \"read my lips: no new taxes\", died in the 1990 budget deal, and now the clip runs in every Democratic ad. In a recession, the broken promise is doing double duty: taxes and trust.", subject = "rep", trigger = EventTrigger.Scheduled(turn = 0), choices = listOf(EventChoice(id = "r_regret", text = "Call the tax deal a mistake: say you'd veto it today.", side = CandidateId.REP, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.04), BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = 0.03), BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = -0.03)), momentum = 2.0, narrative = 2.0), resultText = "The mea culpa softens the middle, and confirms for the base that the pledge meant nothing under pressure."), EventChoice(id = "r_congress", text = "Blame the Democratic Congress that forced your hand.", side = CandidateId.REP, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.03), BlocDelta(blocId = BlocId.SENIORS, margin = 0.02), BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = -0.03)), momentum = 1.0, narrative = -2.0), resultText = "The excuse convinces the convinced. Everyone else remembers whose lips it was."), EventChoice(id = "d_loop", text = "Run the clip on a loop: a promise made, a promise broken.", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.05), BlocDelta(blocId = BlocId.SENIORS, margin = 0.03), BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = -0.02)), momentum = 4.0, narrative = 0.0), resultText = "The tape does the arguing for you, though a campaign of other people's words invites the trust question back."), EventChoice(id = "d_recession", text = "Skip the gotcha: tie the pledge to the recession story.", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.04), BlocDelta(blocId = BlocId.HISPANIC, margin = 0.03), BlocDelta(blocId = BlocId.YOUTH, margin = -0.01)), salienceDeltas = mapOf("economy" to 0.05), momentum = 3.0, narrative = 2.0), resultText = "Broken promise, broken economy: one story now. Less viral, more durable.")), oncePerGame = true),
    GameEvent(id = "h92_culturewar", title = "The Houston 'Culture War' Speech", prompt = "Pat Buchanan takes prime time at the Republican convention and declares \"a religious war... a cultural war\" for the soul of America. The hall roars; the living rooms watching at home go quiet.", subject = "rep", trigger = EventTrigger.Scheduled(turn = 1), choices = listOf(EventChoice(id = "r_embrace", text = "Embrace it: unify the right and run on values.", side = CandidateId.REP, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.05, enthusiasm = 0.03), BlocDelta(blocId = BlocId.SENIORS, margin = 0.02), BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = -0.05), BlocDelta(blocId = BlocId.YOUTH, margin = -0.03)), momentum = 2.0, narrative = -4.0), resultText = "The base comes home loud, and the suburbs watch the speech and quietly leave."), EventChoice(id = "r_soften", text = "Bury the speech: reclaim the podium with a softer family-values key.", side = CandidateId.REP, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.04), BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = 0.03), BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = -0.03)), momentum = 1.0, narrative = 2.0), resultText = "The cleanup reassures the middle, and Buchanan's brigades notice they've been shushed."), EventChoice(id = "d_foil", text = "Make Houston the ad: 'they want a culture war; we want your job back.'", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.05), BlocDelta(blocId = BlocId.YOUTH, margin = 0.04), BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = 0.03), BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = -0.02)), momentum = 4.0, narrative = 3.0), resultText = "The extremism frame writes itself, though culture fights cut both ways with churchgoing Democrats."), EventChoice(id = "d_discipline", text = "Don't touch it: economy, economy, economy.", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.03), BlocDelta(blocId = BlocId.HISPANIC, margin = 0.02)), salienceDeltas = mapOf("economy" to 0.04), momentum = 2.0, narrative = 1.0), resultText = "You leave the gift on the table and keep the frame you're winning on.")), oncePerGame = true),
    GameEvent(id = "h92_warroom", title = "'It's the Economy, Stupid'", prompt = "In Little Rock, James Carville hangs a sign in the war room: \"It's the economy, stupid.\" In Washington, a flailing Bush operation begs James Baker to leave the State Department and take over. Both campaigns pick their machine.", subject = "both", trigger = EventTrigger.Scheduled(turn = 2), choices = listOf(EventChoice(id = "d_sign", text = "Obey the sign: every surrogate, every day, one message.", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.05), BlocDelta(blocId = BlocId.HISPANIC, margin = 0.03), BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = -0.01)), salienceDeltas = mapOf("economy" to 0.06), momentum = 4.0, narrative = 2.0), resultText = "The discipline is total. A one-note campaign, but it's the note the country is humming."), EventChoice(id = "d_broaden", text = "Broaden the case: healthcare and change, not just jobs.", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.04), BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = 0.03), BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = -0.02)), salienceDeltas = mapOf("healthcare" to 0.04), momentum = 2.0, narrative = 3.0), resultText = "The fuller agenda impresses the persuadables, and dilutes the sledgehammer."), EventChoice(id = "r_baker", text = "Pull Baker off Foggy Bottom to run the campaign.", side = CandidateId.REP, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = 0.03), BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.03), BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = -0.01)), momentum = 3.0, narrative = -1.0), resultText = "The pros take the wheel and the operation sharpens overnight, but 'shake-up' is itself a story about a campaign in trouble."), EventChoice(id = "r_recovery", text = "Insist the recovery has begun: the numbers are turning.", side = CandidateId.REP, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.SENIORS, margin = 0.03), BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = 0.02), BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = -0.04)), momentum = 1.0, narrative = -2.0), resultText = "The charts may be right; the checkout lines don't care. 'Out of touch' writes itself.")), oncePerGame = true),
    GameEvent(id = "h92_perot", title = "Perot Drops Out, and Roars Back In", prompt = "Ross Perot quit the race in July, citing a 'revitalized' Democratic Party, then re-enters in October with an infomercial budget and 'giant sucking sound' charts. Nineteen percent of the country is shopping. Both tickets want the same customers.", subject = "both", trigger = EventTrigger.Scheduled(turn = 3), choices = listOf(EventChoice(id = "d_court", text = "Court the Perot voter: deficits, reform, outsider energy.", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.04), BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = 0.03), BlocDelta(blocId = BlocId.BLACK, margin = -0.02)), salienceDeltas = mapOf("taxes" to 0.03), momentum = 3.0, narrative = 2.0), resultText = "The deficit-hawk detour wins a hearing with the angry middle, while your base wonders where you went."), EventChoice(id = "d_hold", text = "Let Perot split the protest vote: keep your own change message.", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.YOUTH, margin = 0.03), BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.02), BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = -0.02)), momentum = 2.0, narrative = 1.0), resultText = "You stay on message and let the arithmetic work. Betting the sucking sound siphons the other guy."), EventChoice(id = "r_flatter", text = "Flatter Perot's voters: you share their deficit worry.", side = CandidateId.REP, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = 0.03), BlocDelta(blocId = BlocId.SENIORS, margin = 0.03), BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = -0.02)), momentum = 2.0, narrative = 1.0), resultText = "The courtship is polite and mostly unrequited: his voters remember whose deficit it is."), EventChoice(id = "r_unstable", text = "Paint Perot as unstable: a protest, not a president.", side = CandidateId.REP, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.SENIORS, margin = 0.03), BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.02), BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = -0.04)), momentum = 1.0, narrative = -2.0), resultText = "The 'crazy Uncle Ross' line lands with some, and insults every voter who was leaning his way.")), oncePerGame = true),
    GameEvent(id = "h92_character", title = "The Draft Letter and the Character War", prompt = "Clinton's 1969 letter thanking an ROTC colonel for \"saving me from the draft\" surfaces, joining Gennifer Flowers in the character file. The Bush campaign smells the only opening it has left.", subject = "dem", trigger = EventTrigger.Scheduled(turn = 4), choices = listOf(EventChoice(id = "d_faceit", text = "Face it head-on: release everything, answer every question, pivot to jobs.", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.04), BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = 0.03), BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = -0.02)), momentum = 3.0, narrative = 3.0), resultText = "The marathon answers drain the pool of questions. Wounded, but still standing, and back on the economy by Friday."), EventChoice(id = "d_distraction", text = "Call it the politics of distraction from a failed economy.", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.04), BlocDelta(blocId = BlocId.YOUTH, margin = 0.03), BlocDelta(blocId = BlocId.SENIORS, margin = -0.03), BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = -0.02)), momentum = 2.0, narrative = -1.0), resultText = "The counterpunch keeps you on offense, and never quite answers the question older voters keep asking."), EventChoice(id = "r_press", text = "Press it: the draft, the trust gap, 'Slick Willie.'", side = CandidateId.REP, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.SENIORS, margin = 0.04), BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.03), BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = -0.03), BlocDelta(blocId = BlocId.YOUTH, margin = -0.02)), momentum = 3.0, narrative = -2.0), resultText = "The doubts take root with veterans and seniors, and the all-attack diet reminds everyone you'd rather not discuss the economy."), EventChoice(id = "r_stature", text = "Stay above it: experience and world leadership.", side = CandidateId.REP, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.SENIORS, margin = 0.04), BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.03), BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = -0.02)), momentum = 2.0, narrative = 2.0), resultText = "The commander-in-chief posture is dignified, and leaves your sharpest weapon in its sheath.")), oncePerGame = true),
    GameEvent(id = "h92_townhall", title = "The Richmond Town Hall", prompt = "The first town-hall debate in presidential history. A woman asks how the national debt has personally affected each candidate. One of you will walk toward her; one of you will glance at his watch. Choose who you are.", subject = "both", trigger = EventTrigger.Scheduled(turn = 6), choices = listOf(EventChoice(id = "connect", text = "Walk toward the questioner: feel their pain, name their town.", effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.06), BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.04), BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = -0.01)), momentum = 6.0, narrative = 7.0), resultText = "You close the distance in every sense. The format was built for this, and now everyone knows it."), EventChoice(id = "prosecute", text = "Prosecute trust and taxes, even in the soft format.", effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.04, enthusiasm = 0.02), BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = -0.03)), momentum = 2.0, narrative = -3.0), resultText = "The hits land clean, and attacking in a living-room format reads colder than it felt on stage."), EventChoice(id = "endure", text = "Get through it: this format was never your friend.", effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = -0.04), BlocDelta(blocId = BlocId.SENIORS, margin = -0.02)), momentum = -3.0, narrative = -5.0), resultText = "The camera catches you checking your watch. Ten seconds of tape, a week of coverage.")), isDebate = true, oncePerGame = true)
)

val HIST_1988: List<GameEvent> = listOf(
    GameEvent(id = "h88_lead", title = "A 17-Point Lead Meets 'Read My Lips'", prompt = "Dukakis leaves his convention up seventeen points on \"competence, not ideology.\" Bush answers in New Orleans with a pledge written to be remembered: \"Read my lips: no new taxes.\" Summer is over. Pick your posture.", subject = "both", trigger = EventTrigger.Scheduled(turn = 0), choices = listOf(EventChoice(id = "d_sit", text = "Sit on the lead: competence, not ideology, and no unforced errors.", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = 0.04), BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.03), BlocDelta(blocId = BlocId.BLACK, margin = -0.02), BlocDelta(blocId = BlocId.YOUTH, margin = -0.02)), momentum = 1.0, narrative = 0.0), resultText = "You protect the lead by not using it. The other side spends August defining you unanswered."), EventChoice(id = "d_define", text = "Punch first: define Bush as a Reagan echo before he defines you.", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.03), BlocDelta(blocId = BlocId.YOUTH, margin = 0.03), BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = -0.02)), momentum = 3.0, narrative = -1.0), resultText = "Going negative early is off-brand for Mr. Competence, but nobody gets to paint you passive."), EventChoice(id = "r_lips", text = "'Read my lips: no new taxes': a pledge carved in granite.", side = CandidateId.REP, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.05, enthusiasm = 0.02), BlocDelta(blocId = BlocId.SENIORS, margin = 0.03), BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = -0.02)), salienceDeltas = mapOf("taxes" to 0.05), momentum = 5.0, narrative = 3.0), resultText = "The line brings the Reagan coalition home, and mortgages a future you'll have to pay for in office."), EventChoice(id = "r_kinder", text = "'A kinder, gentler nation': soften the edge, run as your own man.", side = CandidateId.REP, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.04), BlocDelta(blocId = BlocId.SENIORS, margin = 0.03), BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = -0.02)), momentum = 3.0, narrative = 3.0), resultText = "The gentler brand reassures the suburbs, and the true believers hear an apology for the Reagan years.")), oncePerGame = true),
    GameEvent(id = "h88_flag", title = "The Pledge and the Card-Carrying Member", prompt = "Bush hammers Dukakis's veto of a mandatory Pledge of Allegiance bill and his line that he's a \"card-carrying member of the ACLU.\" It's patriotism as a wedge, and it's working.", subject = "dem", trigger = EventTrigger.Scheduled(turn = 1), choices = listOf(EventChoice(id = "d_principle", text = "Defend the veto on constitutional principle.", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = 0.04), BlocDelta(blocId = BlocId.YOUTH, margin = 0.03), BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = -0.04), BlocDelta(blocId = BlocId.SENIORS, margin = -0.03)), momentum = 0.0, narrative = -2.0), resultText = "You're right on the law and losing on the flag. Con-law seminars applaud; VFW halls don't."), EventChoice(id = "d_factory", text = "Wrap yourself in it: flag factory visit, veterans on the stage.", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.03), BlocDelta(blocId = BlocId.SENIORS, margin = 0.03), BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = -0.02), BlocDelta(blocId = BlocId.YOUTH, margin = -0.02)), momentum = 2.0, narrative = -1.0), resultText = "The photo-op stops some bleeding, but playing defense on patriotism is still defense."), EventChoice(id = "r_press", text = "Press it: 'a card-carrying member of the ACLU' in every stump speech.", side = CandidateId.REP, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.05), BlocDelta(blocId = BlocId.SENIORS, margin = 0.04), BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = -0.02), BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = -0.02)), momentum = 4.0, narrative = -2.0), resultText = "The wedge splits clean. The commentariat calls it cynical; the crowds chant the Pledge."), EventChoice(id = "r_easeoff", text = "Ease off: pivot to peace and prosperity while you're ahead on it.", side = CandidateId.REP, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.04), BlocDelta(blocId = BlocId.SENIORS, margin = 0.03), BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = -0.02)), momentum = 2.0, narrative = 3.0), resultText = "The positive turn reads as confidence, and shelves the sharpest wedge you had.")), oncePerGame = true),
    GameEvent(id = "h88_horton", title = "The Furlough Ads", prompt = "An outside group puts Willie Horton's mugshot on the air: a convicted murderer who committed rape on a Massachusetts weekend furlough, and the official campaign's 'revolving door' ad follows. Crime, race, and fear, all in thirty seconds.", subject = "dem", trigger = EventTrigger.Scheduled(turn = 2), choices = listOf(EventChoice(id = "r_run", text = "Let it all run: crime is the message now.", side = CandidateId.REP, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.05), BlocDelta(blocId = BlocId.SENIORS, margin = 0.04), BlocDelta(blocId = BlocId.BLACK, margin = -0.04), BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = -0.02)), salienceDeltas = mapOf("law_and_order" to 0.06, "race_policing" to 0.04), momentum = 4.0, narrative = -3.0), resultText = "The ads move numbers you can chart by the day, and buy a permanent asterisk on how you won."), EventChoice(id = "r_arms_length", text = "Keep the official campaign clean: talk furlough policy, not the mugshot.", side = CandidateId.REP, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.03), BlocDelta(blocId = BlocId.SENIORS, margin = 0.03), BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = -0.02)), salienceDeltas = mapOf("law_and_order" to 0.03), momentum = 2.0, narrative = 2.0), resultText = "Deniability holds and the issue still cuts: just slower, and without the ugliest edge."), EventChoice(id = "d_smear", text = "Call the ad what it is: a racial smear.", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.BLACK, margin = 0.05, enthusiasm = 0.02), BlocDelta(blocId = BlocId.YOUTH, margin = 0.04), BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = -0.04), BlocDelta(blocId = BlocId.SENIORS, margin = -0.03)), momentum = 1.0, narrative = -1.0), resultText = "Naming it rallies your coalition, and keeps the mugshot on television another two weeks."), EventChoice(id = "d_merits", text = "Answer on the merits: the furlough data, the Republican programs like it.", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.03), BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = 0.02), BlocDelta(blocId = BlocId.BLACK, margin = -0.02)), momentum = 1.0, narrative = 1.0), resultText = "The technocratic rebuttal is accurate and bloodless. Fear beats footnotes most weeks.")), oncePerGame = true),
    GameEvent(id = "h88_tank", title = "The Tank", prompt = "Trailing on defense, the Dukakis campaign books an M1 Abrams at a General Dynamics plant in Michigan. The candidate can climb in, helmet and all, or give the sober arms-control speech his wonks drafted.", subject = "dem", trigger = EventTrigger.Scheduled(turn = 3), choices = listOf(EventChoice(id = "d_ride", text = "Take the ride: helmet on, prove you're no dove.", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.02), BlocDelta(blocId = BlocId.SENIORS, margin = -0.03), BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = -0.02)), momentum = -3.0, narrative = -6.0), resultText = "The helmet, the grin, the lurching turret. The picture is supposed to say strength; it says Halloween."), EventChoice(id = "d_speech", text = "Skip the stunt: a sober defense speech at Georgetown.", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = 0.04), BlocDelta(blocId = BlocId.SENIORS, margin = 0.02), BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = -0.02)), momentum = 1.0, narrative = 2.0), resultText = "Substance without a picture. It moves few voters, and hands the other side nothing to loop."), EventChoice(id = "r_mock", text = "Cut the mocking ad tonight: the footage is a gift.", side = CandidateId.REP, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.04), BlocDelta(blocId = BlocId.SENIORS, margin = 0.03), BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = -0.02)), momentum = 4.0, narrative = -1.0), resultText = "The ad writes itself and the laughter does the rest, though gleeful mockery has a shelf life with the undecided."), EventChoice(id = "r_gravitas", text = "Stay presidential: let the pictures speak for themselves.", side = CandidateId.REP, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.03), BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = 0.02), BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = -0.02)), momentum = 2.0, narrative = 2.0), resultText = "Restraint reads as stature. The base wanted the joke told louder.")), oncePerGame = true),
    GameEvent(id = "h88_vpdebate", title = "'You're No Jack Kennedy'", prompt = "Bentsen and Quayle in Omaha. Quayle has been comparing his experience to JFK's for weeks, and everyone on both staffs knows the counterpunch is loaded. What's the brief for your number two?", subject = "both", trigger = EventTrigger.Scheduled(turn = 5), choices = listOf(EventChoice(id = "zinger", text = "Arm the kill shot: if the opening comes, take it.", effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = 0.04), BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.04), BlocDelta(blocId = BlocId.YOUTH, margin = 0.03), BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = -0.01)), momentum = 5.0, narrative = 6.0), resultText = "\"Senator, you're no Jack Kennedy.\" The hall gasps, the clip runs forever, and a few voters flinch at the cruelty."), EventChoice(id = "safe", text = "Keep the undercard safe: no risks, no headlines.", effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.SENIORS, margin = 0.03), BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.02)), momentum = 2.0, narrative = 1.0), resultText = "A forgettable night, which, for a running mate, is a kind of victory.")), isDebate = true, oncePerGame = true),
    GameEvent(id = "h88_debate2", title = "The Death-Penalty Question", prompt = "Second debate, Los Angeles. Bernard Shaw opens with a hypothetical no one is ready for: if your spouse were raped and murdered, would you favor the death penalty for the killer? The country leans in. Answer as a person or as a position paper.", subject = "both", trigger = EventTrigger.Scheduled(turn = 6), choices = listOf(EventChoice(id = "human", text = "Let them see the human being: anger first, policy second.", effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.05), BlocDelta(blocId = BlocId.SENIORS, margin = 0.04), BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.02), BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = -0.01)), momentum = 4.0, narrative = 5.0), resultText = "The flash of real feeling lands harder than any ten-point plan. Voters remember that you bled."), EventChoice(id = "clinical", text = "Hold the line: a calm, consistent policy answer, no theater.", effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = 0.03), BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = -0.04), BlocDelta(blocId = BlocId.SENIORS, margin = -0.04)), momentum = -3.0, narrative = -6.0), resultText = "Principled, consistent, and bloodless. The passionless answer to an unthinkable question haunts the tape.")), isDebate = true, oncePerGame = true)
)

val HIST_1984: List<GameEvent> = listOf(
    GameEvent(id = "h84_morning", title = "Morning in America", prompt = "Inflation is down, the recovery is roaring, and the Tuesday Team's sunrise ads, \"It's morning again in America\", are the best political television anyone has made. Mondale has to argue with the weather.", subject = "rep", trigger = EventTrigger.Scheduled(turn = 0), choices = listOf(EventChoice(id = "r_sunny", text = "Run the sunshine: prouder, stronger, better.", side = CandidateId.REP, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.05), BlocDelta(blocId = BlocId.SENIORS, margin = 0.04), BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.03), BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = -0.01)), salienceDeltas = mapOf("economy" to 0.04), momentum = 5.0, narrative = 4.0), resultText = "The ads glow. So does the deficit chart your opponent keeps waving. For the voters who read charts."), EventChoice(id = "r_rerun", text = "Go after Mondale as Carter's vice president: the rerun nobody ordered.", side = CandidateId.REP, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.04), BlocDelta(blocId = BlocId.SENIORS, margin = 0.03), BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = -0.03)), momentum = 3.0, narrative = -2.0), resultText = "The Carter hangover still aches, though attack ads clash with the morning-in-America soundtrack."), EventChoice(id = "d_deficits", text = "Puncture the glow: deficits, fairness, who got left out.", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.BLACK, margin = 0.04), BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.03), BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = 0.02), BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = -0.02)), salienceDeltas = mapOf("taxes" to 0.04), momentum = 2.0, narrative = 1.0), resultText = "The fairness case is real and the room is listening. It's the country that's at the beach."), EventChoice(id = "d_dawn", text = "Don't argue with the sunshine: offer your own vision of the future.", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.YOUTH, margin = 0.03), BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.03), BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = -0.02)), momentum = 2.0, narrative = 2.0), resultText = "Hope versus hope is a fairer fight than gloom versus hope, even if their production budget is bigger.")), oncePerGame = true),
    GameEvent(id = "h84_taxes", title = "'He Won't Tell You. I Just Did.'", prompt = "At the San Francisco convention, Mondale says the unsayable: \"Mr. Reagan will raise taxes, and so will I. He won't tell you. I just did.\" Historic candor, and a thirty-second attack ad, depending on who's cutting the tape.", subject = "dem", trigger = EventTrigger.Scheduled(turn = 1), choices = listOf(EventChoice(id = "d_own", text = "Own the candor: honesty is the character argument.", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = 0.04), BlocDelta(blocId = BlocId.SENIORS, margin = 0.02), BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = -0.05), BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = -0.03)), salienceDeltas = mapOf("taxes" to 0.06), momentum = 1.0, narrative = 3.0), resultText = "Historians will love it. Voters hear one word, and the word is 'taxes.'"), EventChoice(id = "d_fairness", text = "Reframe fast: taxes on the wealthy only; fairness, not pain.", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.BLACK, margin = 0.04), BlocDelta(blocId = BlocId.YOUTH, margin = 0.03), BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = -0.02), BlocDelta(blocId = BlocId.SENIORS, margin = -0.02)), salienceDeltas = mapOf("taxes" to 0.04), momentum = 1.0, narrative = 1.0), resultText = "The cleanup muddies the candor that was the whole point, and the ad still writes itself."), EventChoice(id = "r_pounce", text = "Cut the ad by Friday: 'he promised to raise your taxes.'", side = CandidateId.REP, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.05), BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.03), BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = -0.01)), salienceDeltas = mapOf("taxes" to 0.05), momentum = 4.0, narrative = 1.0), resultText = "The gift is accepted and gift-wrapped back. Fact-checkers note your own math quietly doesn't add up either."), EventChoice(id = "r_ignore", text = "Barely mention him: optimism is the sharper knife.", side = CandidateId.REP, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.04), BlocDelta(blocId = BlocId.SENIORS, margin = 0.03), BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = -0.01)), momentum = 3.0, narrative = 3.0), resultText = "You stay sunny and let his own sentence chase him around the country.")), oncePerGame = true),
    GameEvent(id = "h84_ferraro", title = "Ferraro: History, Then the Finances", prompt = "Geraldine Ferraro is the first woman on a major-party ticket, and the crowds are electric. Then the questions start about her husband's real-estate business and the tax returns he doesn't want to release.", subject = "dem", trigger = EventTrigger.Scheduled(turn = 2), choices = listOf(EventChoice(id = "d_history", text = "Run on the history: put her everywhere, ride the energy.", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.05), BlocDelta(blocId = BlocId.YOUTH, margin = 0.04), BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = 0.03), BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = -0.03), BlocDelta(blocId = BlocId.SENIORS, margin = -0.02)), momentum = 4.0, narrative = 3.0), resultText = "The rope lines are electric, and every day she headlines is a day the finance questions ride along."), EventChoice(id = "d_disclose", text = "Get ahead of it: release the returns, a marathon press conference.", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.03), BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = 0.03), BlocDelta(blocId = BlocId.YOUTH, margin = -0.02)), momentum = 0.0, narrative = 3.0), resultText = "She takes every question for two hours and the story deflates, but you spent a precious week off message."), EventChoice(id = "r_hands_off", text = "Stay out of it: let the papers do the digging.", side = CandidateId.REP, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.SENIORS, margin = 0.03), BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.02), BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = -0.01)), momentum = 2.0, narrative = 1.0), resultText = "Clean hands, same damage. The story runs fine without your fingerprints."), EventChoice(id = "r_vetting", text = "Question the vetting: is the ticket ready?", side = CandidateId.REP, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.03), BlocDelta(blocId = BlocId.SENIORS, margin = 0.02), BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = -0.04)), momentum = 1.0, narrative = -2.0), resultText = "The attack scores on paper, and reads as piling on the first woman ever on a ticket.")), oncePerGame = true),
    GameEvent(id = "h84_debate1", title = "First Debate (Louisville): The Stumble", prompt = "Louisville. The oldest president in history rambles, loses threads, and closes badly; the challenger is crisp, respectful, and suddenly relevant. By morning the papers are asking the age question out loud. Play the night.", subject = "both", trigger = EventTrigger.Scheduled(turn = 4), choices = listOf(EventChoice(id = "crisp", text = "Be crisp and relentless: expose every fogged answer, respectfully.", effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = 0.05), BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.04), BlocDelta(blocId = BlocId.SENIORS, margin = -0.03)), momentum = 6.0, narrative = 6.0), resultText = "For one night the race is alive. 'The age issue' leads every broadcast, and seniors bristle at the subtext."), EventChoice(id = "coast", text = "Protect what you have: short answers, no risks.", effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = -0.04), BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = -0.03)), momentum = -4.0, narrative = -5.0), resultText = "Cautious reads as foggy. The morning-after analysis is brutal, and the question won't wait.")), isDebate = true, oncePerGame = true),
    GameEvent(id = "h84_bear", title = "The Bear in the Woods", prompt = "The Tuesday Team's other masterpiece: a grizzly prowls the treeline while a voice asks, \"There is a bear in the woods... isn't it smart to be as strong as the bear?\" Strength as a bedtime story, with a nuclear-freeze movement marching outside.", subject = "rep", trigger = EventTrigger.Scheduled(turn = 5), choices = listOf(EventChoice(id = "r_bear", text = "Air the bear: strength against an uncertain world.", side = CandidateId.REP, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.SENIORS, margin = 0.04), BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.04), BlocDelta(blocId = BlocId.YOUTH, margin = -0.03), BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = -0.01)), salienceDeltas = mapOf("law_and_order" to 0.04), momentum = 3.0, narrative = 2.0), resultText = "The parable lands with everyone who remembers the Cold War is on, and spooks the young voters who dream about it."), EventChoice(id = "r_sunshine", text = "Shelve the fear: sunshine is the brand, stick to it.", side = CandidateId.REP, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.04), BlocDelta(blocId = BlocId.YOUTH, margin = 0.02), BlocDelta(blocId = BlocId.SENIORS, margin = -0.02)), momentum = 2.0, narrative = 3.0), resultText = "The lighter touch keeps the coalition comfortable, and cedes the strength frame you owned."), EventChoice(id = "d_freeze", text = "Answer with the freeze: arms control as the moral issue.", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.YOUTH, margin = 0.05), BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = 0.04), BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = -0.03), BlocDelta(blocId = BlocId.SENIORS, margin = -0.02)), momentum = 2.0, narrative = 1.0), resultText = "The freeze movement finds its candidate, and the 'weak on defense' ad finds its footage."), EventChoice(id = "d_mock", text = "Mock it: 'there is no bear.'", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = 0.03), BlocDelta(blocId = BlocId.YOUTH, margin = 0.02), BlocDelta(blocId = BlocId.SENIORS, margin = -0.03)), momentum = 1.0, narrative = -1.0), resultText = "The joke gets a laugh in the hall, and out in the country, plenty of voters think there is a bear.")), oncePerGame = true),
    GameEvent(id = "h84_debate2", title = "'I Will Not Exploit My Opponent's Youth'", prompt = "Kansas City, second debate. The age question is coming: everyone in both camps knows it. One rehearsed line can end the issue forever, or one bad night can crack the race open. Choose the plan.", subject = "both", trigger = EventTrigger.Scheduled(turn = 6), choices = listOf(EventChoice(id = "humor", text = "Disarm with the line of the night: humor kills the question.", effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.05), BlocDelta(blocId = BlocId.SENIORS, margin = 0.05), BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.03), BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = -0.01)), momentum = 7.0, narrative = 8.0), resultText = "\"I will not exploit, for political purposes, my opponent's youth and inexperience.\" Even your opponent laughs. The issue dies in the room."), EventChoice(id = "substance", text = "Prosecute on substance: arms control detail, no jokes.", requires = TraitRequirement(trait = "policyKnowledge", min = 70.0), effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = 0.05), BlocDelta(blocId = BlocId.YOUTH, margin = 0.02), BlocDelta(blocId = BlocId.SENIORS, margin = 0.02)), momentum = 4.0, narrative = 3.0), resultText = "You win the transcript. The other side is playing for the highlight reel, and the highlight is what gets replayed.")), isDebate = true, oncePerGame = true)
)

val HIST_1980: List<GameEvent> = listOf(
    GameEvent(id = "h80_misery", title = "The Misery Index", prompt = "Inflation near 13 percent, interest rates over 15, gas lines in living memory. The 'misery index' Carter used against Ford in 1976 is now aimed at him. And 52 Americans are still hostage in Tehran. Frame the economy.", subject = "both", trigger = EventTrigger.Scheduled(turn = 0), choices = listOf(EventChoice(id = "d_candor", text = "Level with the country: inflation is brutal, here is the plan.", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.SENIORS, margin = 0.04), BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = 0.03), BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = -0.03)), salienceDeltas = mapOf("economy" to 0.05), momentum = 2.0, narrative = 3.0), resultText = "Candor earns respect it can't quite convert: the plan is sober, and the grocery bill is still the grocery bill."), EventChoice(id = "d_risky", text = "Change the subject. Reagan is too dangerous for the button.", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.04), BlocDelta(blocId = BlocId.SENIORS, margin = 0.03), BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = -0.03), BlocDelta(blocId = BlocId.YOUTH, margin = -0.01)), momentum = 2.0, narrative = -1.0), resultText = "The fear frame moves cautious voters, and running from your own record is its own admission."), EventChoice(id = "r_betteroff", text = "'Are you better off than you were four years ago?': ask it everywhere.", side = CandidateId.REP, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.05), BlocDelta(blocId = BlocId.SENIORS, margin = 0.03), BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.02), BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = -0.02)), salienceDeltas = mapOf("economy" to 0.06), momentum = 5.0, narrative = 3.0), resultText = "The question answers itself at every kitchen table, though repeating it invites scrutiny of your own arithmetic."), EventChoice(id = "r_kemp", text = "Sell the cure: a 30 percent across-the-board tax cut.", side = CandidateId.REP, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.04), BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = -0.03), BlocDelta(blocId = BlocId.SENIORS, margin = -0.02)), salienceDeltas = mapOf("taxes" to 0.05), momentum = 3.0, narrative = 0.0), resultText = "The supply-side gospel thrills the faithful, and 'voodoo economics' was coined by your own running mate.")), oncePerGame = true),
    GameEvent(id = "h80_gaffes", title = "Noble Causes and a Dangerous Cowboy", prompt = "Reagan opens the fall calling Vietnam a \"noble cause,\" jokes about the Klan in the wrong state, and blames trees for pollution. Every stumble feeds the Carter frame: a trigger-happy cowboy who can't be trusted with the button.", subject = "rep", trigger = EventTrigger.Scheduled(turn = 1), choices = listOf(EventChoice(id = "r_discipline", text = "Tighten the operation: Stu Spencer on the plane, script the stops.", side = CandidateId.REP, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.04), BlocDelta(blocId = BlocId.SENIORS, margin = 0.03), BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = -0.02)), momentum = 3.0, narrative = 3.0), resultText = "The gaffe rate drops to zero and the 'dangerous' frame starves, while the let-Reagan-be-Reagan crowd grumbles about the leash."), EventChoice(id = "r_unleashed", text = "Let Reagan be Reagan: apologize for nothing.", side = CandidateId.REP, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.05, enthusiasm = 0.02), BlocDelta(blocId = BlocId.SENIORS, margin = -0.03), BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = -0.04)), momentum = 2.0, narrative = -3.0), resultText = "The crowds love the unfiltered version, and every ad-lib is a fresh exhibit for the cowboy prosecution."), EventChoice(id = "d_dangerous", text = "Press the frame: a man you can't trust with the button.", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.04), BlocDelta(blocId = BlocId.SENIORS, margin = 0.03), BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = -0.03)), momentum = 3.0, narrative = -1.0), resultText = "The warmonger frame is your best card: played hard enough, it starts to look like the only one you hold."), EventChoice(id = "d_rosegarden", text = "Stay presidential: the Rose Garden, not the gutter.", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = 0.03), BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.02), BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = -0.02)), momentum = 1.0, narrative = 2.0), resultText = "The above-it-all posture preserves dignity, and lets his stumbles fade unexploited.")), oncePerGame = true),
    GameEvent(id = "h80_anderson", title = "The Anderson Problem", prompt = "John Anderson, liberal Republican turned independent, polls in the teens, and the League of Women Voters invites him to the Baltimore debate. Carter refuses to share a stage with him. Reagan has to decide whether to show up anyway.", subject = "both", trigger = EventTrigger.Scheduled(turn = 2), choices = listOf(EventChoice(id = "d_skip", text = "Skip Baltimore: don't elevate a spoiler who bleeds your vote.", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.BLACK, margin = 0.02), BlocDelta(blocId = BlocId.SENIORS, margin = 0.02), BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = -0.04), BlocDelta(blocId = BlocId.YOUTH, margin = -0.03)), momentum = -2.0, narrative = -4.0), resultText = "Strategically defensible, optically terrible. The empty-podium jokes write themselves for a week."), EventChoice(id = "d_attend", text = "Show up and fight two fronts at once.", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = 0.03), BlocDelta(blocId = BlocId.YOUTH, margin = 0.03), BlocDelta(blocId = BlocId.SENIORS, margin = -0.02)), momentum = 1.0, narrative = 1.0), resultText = "You deny them the empty chair, and spend the night legitimizing the man taking your voters."), EventChoice(id = "r_debate", text = "Debate Anderson solo: look unafraid, let Carter wear the empty chair.", side = CandidateId.REP, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = 0.04), BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.03), BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = -0.01)), momentum = 3.0, narrative = 3.0), resultText = "A civil, confident night, and the story is the man who didn't come."), EventChoice(id = "r_twoman", text = "Decline too: force a two-man race on your terms.", side = CandidateId.REP, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.03), BlocDelta(blocId = BlocId.SENIORS, margin = 0.02), BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = -0.02)), momentum = 2.0, narrative = 0.0), resultText = "You keep the frame simple, and pass up a free night of prime time.")), oncePerGame = true),
    GameEvent(id = "h80_meanness", title = "The 'Meanness' Problem", prompt = "Carter suggests Reagan would divide the country \"black from white, Jew from Christian\" and run a campaign of hatred. The press piles on, not on Reagan, but on Carter's tone. The 'meanness' story now shadows the incumbent.", subject = "dem", trigger = EventTrigger.Scheduled(turn = 4), choices = listOf(EventChoice(id = "d_walkback", text = "Concede you got carried away: the Barbara Walters walk-back.", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.04), BlocDelta(blocId = BlocId.SENIORS, margin = 0.03), BlocDelta(blocId = BlocId.BLACK, margin = -0.02), BlocDelta(blocId = BlocId.YOUTH, margin = -0.02)), momentum = 1.0, narrative = 2.0), resultText = "The contrition stops the pile-on, and reads to your base like you apologized for telling the truth."), EventChoice(id = "d_swing", text = "Keep swinging: some things are worth naming.", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.BLACK, margin = 0.04, enthusiasm = 0.02), BlocDelta(blocId = BlocId.YOUTH, margin = 0.03), BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = -0.04), BlocDelta(blocId = BlocId.SENIORS, margin = -0.03)), momentum = 0.0, narrative = -4.0), resultText = "The base hears conviction; everyone else hears the meanness story confirmed in your own voice."), EventChoice(id = "r_sorrow", text = "More in sorrow than in anger: 'I'm saddened by the President's tone.'", side = CandidateId.REP, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.05), BlocDelta(blocId = BlocId.SENIORS, margin = 0.03), BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = -0.01)), momentum = 3.0, narrative = 4.0), resultText = "The wounded-gentleman act is devastating precisely because it isn't an attack, though the base wanted the counterpunch."), EventChoice(id = "r_counter", text = "Hit back: his record is the real meanness.", side = CandidateId.REP, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.04), BlocDelta(blocId = BlocId.SENIORS, margin = 0.02), BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = -0.03)), momentum = 2.0, narrative = -2.0), resultText = "The counterattack lands, and forfeits the high ground the other man's temper just handed you.")), oncePerGame = true),
    GameEvent(id = "h80_hostages", title = "October Surprise Watch", prompt = "The hostage crisis nears its first anniversary. On Election Day itself. Every rumor of a deal moves the polls, and both campaigns war-game a release announcement in the final week. Handle the vigil.", subject = "both", trigger = EventTrigger.Scheduled(turn = 5), choices = listOf(EventChoice(id = "d_deal", text = "Push hard for a breakthrough before Election Day.", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.SENIORS, margin = 0.03), BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.03), BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = -0.02), BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = -0.02)), momentum = 2.0, narrative = -2.0), resultText = "Every leak raises hopes the negotiations can't meet, and 'political' starts to taint the diplomacy itself."), EventChoice(id = "d_quiet", text = "Keep the diplomacy quiet: no timelines, no theater.", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = 0.03), BlocDelta(blocId = BlocId.SENIORS, margin = 0.02), BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = -0.02)), momentum = 1.0, narrative = 1.0), resultText = "The sober course protects the talks, and leaves the anniversary coverage to run unanswered."), EventChoice(id = "r_inoculate", text = "Warn of an 'October surprise': inoculate before any deal lands.", side = CandidateId.REP, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.04), BlocDelta(blocId = BlocId.SENIORS, margin = 0.02), BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = -0.03)), momentum = 3.0, narrative = -2.0), resultText = "The pre-buttal works: a late deal now reads as a stunt. Politicizing the hostages carries its own smell."), EventChoice(id = "r_respect", text = "Stay respectful: pray for the hostages, question the weakness.", side = CandidateId.REP, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.04), BlocDelta(blocId = BlocId.SENIORS, margin = 0.03), BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = -0.02)), momentum = 2.0, narrative = 3.0), resultText = "Grace on the crisis, steel on the record: the balance holds, even if the base wanted more brimstone.")), oncePerGame = true),
    GameEvent(id = "h80_debate", title = "The Cleveland Debate", prompt = "After months of maneuvering, one debate. Cleveland, a week out, the largest audience in history. Carter has the facts; Reagan has the temperature. \"There you go again\" is sitting in someone's holster. Play the only night that matters.", subject = "both", trigger = EventTrigger.Scheduled(turn = 7), choices = listOf(EventChoice(id = "reassure", text = "Be warm and unthreatening: 'there you go again.'", effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.06), BlocDelta(blocId = BlocId.SENIORS, margin = 0.05), BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = -0.01)), momentum = 7.0, narrative = 8.0), resultText = "Four words and a chuckle deflate months of the cowboy frame. Voters see a reasonable man, and the fear melts."), EventChoice(id = "closer", text = "End with the question: 'are you better off than you were four years ago?'", effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.05), BlocDelta(blocId = BlocId.SENIORS, margin = 0.04), BlocDelta(blocId = BlocId.YOUTH, margin = -0.01)), salienceDeltas = mapOf("economy" to 0.05), momentum = 6.0, narrative = 5.0), resultText = "The closing question hangs in ten million living rooms. The weekend polls move like weather."), EventChoice(id = "prosecute", text = "Prosecute the record: facts, figures, and the danger of the alternative.", effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = 0.04), BlocDelta(blocId = BlocId.BLACK, margin = 0.02), BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = -0.03)), momentum = 3.0, narrative = -2.0), resultText = "You win the transcript and lose the temperature. Command of detail reads as hectoring next to an easy smile.")), isDebate = true, oncePerGame = true)
)

val HIST_1976: List<GameEvent> = listOf(
    GameEvent(id = "h76_pardon", title = "The Long Shadow of the Pardon", prompt = "Two years on, Ford's pardon of Nixon still defines him for millions of voters. Carter runs as the outsider who will never lie to you. The incumbent has to decide whether to defend the decision or move past it.", subject = "both", trigger = EventTrigger.Scheduled(turn = 0), choices = listOf(EventChoice(id = "d_trust", text = "Run on trust: a government as good as its people.", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.05), BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = 0.04), BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = -0.02)), momentum = 4.0, narrative = 5.0), resultText = "The outsider pitch lands with a country sick of Washington, though it invites scrutiny of a thin resume."), EventChoice(id = "d_south", text = "Lean on the South: a Georgian who can bring it home.", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.05), BlocDelta(blocId = BlocId.BLACK, margin = 0.03), BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = -0.02)), momentum = 3.0, narrative = 2.0), resultText = "The regional pride holds the Solid South together, and reminds Northern liberals how conservative it is."), EventChoice(id = "r_healing", text = "Defend the pardon: it was time to heal the nation.", side = CandidateId.REP, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.SENIORS, margin = 0.04), BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.03), BlocDelta(blocId = BlocId.YOUTH, margin = -0.03)), momentum = 2.0, narrative = 3.0), resultText = "The steady-hand framing reassures the middle, and keeps a settled wound in the headlines."), EventChoice(id = "r_record", text = "Change the subject: whip inflation, steady the ship.", side = CandidateId.REP, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.04), BlocDelta(blocId = BlocId.SENIORS, margin = 0.03), BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = -0.01)), salienceDeltas = mapOf("economy" to 0.05), momentum = 3.0, narrative = 2.0), resultText = "Focusing on the recovery plays to your strengths, and cedes the character argument to the challenger.")), oncePerGame = true),
    GameEvent(id = "h76_playboy", title = "The Playboy Interview", prompt = "Carter tells Playboy magazine he has 'looked on a lot of women with lust' and 'committed adultery in my heart.' The Sunday-school teacher's candor becomes a week of late-night jokes and worried Baptists.", subject = "dem", trigger = EventTrigger.Scheduled(turn = 2), choices = listOf(EventChoice(id = "d_owniit", text = "Own it: honesty is the whole point of this campaign.", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = 0.04), BlocDelta(blocId = BlocId.YOUTH, margin = 0.03), BlocDelta(blocId = BlocId.SENIORS, margin = -0.03)), momentum = 1.0, narrative = 2.0), resultText = "The unflappable candor wins the sophisticates, and rattles the pews you were counting on."), EventChoice(id = "d_contain", text = "Contain it: back to church, back to the stump.", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.SENIORS, margin = 0.04), BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.03), BlocDelta(blocId = BlocId.YOUTH, margin = -0.02)), momentum = 2.0, narrative = 1.0), resultText = "Damage control steadies the base, at the cost of the fearless-truth-teller glow."), EventChoice(id = "r_contrast", text = "Draw the contrast: a steady man makes no such headlines.", side = CandidateId.REP, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.SENIORS, margin = 0.05), BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.03), BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = -0.01)), momentum = 3.0, narrative = 3.0), resultText = "Standing quietly above the circus makes your dullness look like a virtue.")), oncePerGame = true),
    GameEvent(id = "h76_debate1", title = "The First Debate Returns", prompt = "For the first time since 1960, the candidates debate on television. In Philadelphia, the sound cuts out for twenty-seven minutes and both men stand frozen at their podiums. Make the first live matchup in sixteen years count.", subject = "both", trigger = EventTrigger.Scheduled(turn = 3), choices = listOf(EventChoice(id = "command", text = "Command the substance: out-detail your opponent on the economy.", effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = 0.05), BlocDelta(blocId = BlocId.SENIORS, margin = 0.04), BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = -0.01)), salienceDeltas = mapOf("economy" to 0.04), momentum = 6.0, narrative = 6.0), resultText = "You win the transcript. Voters who wanted a competent hand see one."), EventChoice(id = "outsider", text = "Play the outsider: it is you against a broken Washington.", effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.05), BlocDelta(blocId = BlocId.YOUTH, margin = 0.03), BlocDelta(blocId = BlocId.SENIORS, margin = -0.02)), momentum = 5.0, narrative = 4.0), resultText = "The change message cuts through the frozen-audio farce and dominates the recap.")), isDebate = true, oncePerGame = true),
    GameEvent(id = "h76_easterneurope", title = "'No Soviet Domination of Eastern Europe'", prompt = "In the second debate, Ford insists 'there is no Soviet domination of Eastern Europe' and refuses to walk it back for days. To Polish, Czech, and Hungarian voters in the industrial North, it is baffling. The gaffe defines the week.", subject = "rep", trigger = EventTrigger.Scheduled(turn = 4), choices = listOf(EventChoice(id = "r_clarify", text = "Clarify fast: no free people accept domination.", side = CandidateId.REP, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.04), BlocDelta(blocId = BlocId.SENIORS, margin = 0.03), BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = -0.02)), momentum = 2.0, narrative = 2.0), resultText = "The quick correction stops the bleeding in the ethnic wards, a few days late."), EventChoice(id = "r_standfirm", text = "Stand firm for days: refuse to look like you caved.", side = CandidateId.REP, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.SENIORS, margin = 0.02), BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = -0.05), BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = -0.03)), momentum = -3.0, narrative = -5.0), resultText = "The stubbornness reads as out of touch, and the Rust Belt ethnic vote curdles."), EventChoice(id = "d_pounce", text = "Pounce: tell Chicago's Poles who really runs Warsaw.", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.06), BlocDelta(blocId = BlocId.SENIORS, margin = 0.03), BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = -0.02)), momentum = 4.0, narrative = 3.0), resultText = "The gift keeps giving in the industrial North, where the ethnic wards decide states.")), oncePerGame = true),
    GameEvent(id = "h76_closing", title = "The Solid South in the Balance", prompt = "It all comes down to the South and a handful of Northern industrial states. Carter's regional coalition of Black voters and white Southerners is historically fragile. One more push decides where the effort goes.", subject = "both", trigger = EventTrigger.Scheduled(turn = 6), choices = listOf(EventChoice(id = "d_coalition", text = "Hold the coalition: Black turnout and white pride, together.", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.BLACK, margin = 0.06), BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.03), BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = -0.02)), momentum = 4.0, narrative = 3.0), resultText = "The improbable alliance holds one more week, the exact math that wins or loses it all."), EventChoice(id = "d_north", text = "Fight North: labor, Catholics, and the big union states.", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.05), BlocDelta(blocId = BlocId.SENIORS, margin = 0.03), BlocDelta(blocId = BlocId.YOUTH, margin = -0.02)), momentum = 3.0, narrative = 2.0), resultText = "The blue-collar North firms up, and the South is left to hold on its own."), EventChoice(id = "r_sunbelt", text = "Raid the South: peel off the suburbs and the new Sun Belt.", side = CandidateId.REP, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.05), BlocDelta(blocId = BlocId.SENIORS, margin = 0.03), BlocDelta(blocId = BlocId.BLACK, margin = -0.03)), momentum = 3.0, narrative = 2.0), resultText = "The suburban South is winnable, and every point there stretches the challenger thin."), EventChoice(id = "r_west", text = "Lock the West: run up the Mountain and Plains margins.", side = CandidateId.REP, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.04), BlocDelta(blocId = BlocId.SENIORS, margin = 0.03), BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = -0.01)), momentum = 2.0, narrative = 1.0), resultText = "The West is friendly ground, and banking it frees you to fight elsewhere.")), oncePerGame = true)
)

val HIST_1972: List<GameEvent> = listOf(
    GameEvent(id = "h72_eagleton", title = "The Eagleton Affair", prompt = "Days after the convention, it emerges that running mate Thomas Eagleton was hospitalized for depression and given electroshock therapy. McGovern says he backs him 'one thousand percent,' then drops him within the week. The reversal defines the ticket.", subject = "dem", trigger = EventTrigger.Scheduled(turn = 0), choices = listOf(EventChoice(id = "d_stand", text = "Stand by him: loyalty over the pundits.", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.YOUTH, margin = 0.04), BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = 0.02), BlocDelta(blocId = BlocId.SENIORS, margin = -0.04)), momentum = -2.0, narrative = -3.0), resultText = "The base admires the loyalty; the wider country sees a health question left hanging."), EventChoice(id = "d_replace", text = "Cut him loose and reset with a Kennedy in-law.", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.SENIORS, margin = 0.03), BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.02), BlocDelta(blocId = BlocId.YOUTH, margin = -0.04)), momentum = -1.0, narrative = -4.0), resultText = "The reset stops one story and starts another: the 'thousand percent' line follows you for weeks."), EventChoice(id = "r_competence", text = "Let it speak for itself: a question of competence.", side = CandidateId.REP, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.05), BlocDelta(blocId = BlocId.SENIORS, margin = 0.04), BlocDelta(blocId = BlocId.YOUTH, margin = -0.01)), momentum = 4.0, narrative = 3.0), resultText = "Saying little says everything. The chaos on the other ticket is its own best ad.")), oncePerGame = true),
    GameEvent(id = "h72_amnesty", title = "Acid, Amnesty, and Abortion", prompt = "A Democratic rival's line, that McGovern stands for 'acid, amnesty, and abortion,' has stuck to him like tar. The campaign has to decide whether to fight the caricature or lean into the movement that made it.", subject = "both", trigger = EventTrigger.Scheduled(turn = 2), choices = listOf(EventChoice(id = "d_pivot", text = "Pivot to the center: tax reform and bringing the boys home.", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.05), BlocDelta(blocId = BlocId.SENIORS, margin = 0.03), BlocDelta(blocId = BlocId.YOUTH, margin = -0.03)), salienceDeltas = mapOf("economy" to 0.04), momentum = 3.0, narrative = 2.0), resultText = "The move to the middle wins a hearing from wavering Democrats, and dims the crusade that got you here."), EventChoice(id = "d_movement", text = "Own the movement: end the war, feed the poor, no apologies.", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.YOUTH, margin = 0.06, enthusiasm = 0.03), BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = 0.04), BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = -0.05)), momentum = 3.0, narrative = 0.0), resultText = "The true believers surge, and the old Roosevelt coalition drifts further out of reach."), EventChoice(id = "r_silentmajority", text = "Speak for the silent majority: order against chaos.", side = CandidateId.REP, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.06), BlocDelta(blocId = BlocId.SENIORS, margin = 0.04), BlocDelta(blocId = BlocId.YOUTH, margin = -0.03)), salienceDeltas = mapOf("law_and_order" to 0.05), momentum = 4.0, narrative = 2.0), resultText = "The framing writes itself and pulls in Democrats who no longer recognize their party.")), oncePerGame = true),
    GameEvent(id = "h72_watergate", title = "A Third-Rate Burglary", prompt = "The Washington Post keeps tying a June break-in at the Watergate to the Nixon campaign. The White House calls it a third-rate burglary. It barely moves the polls, and the fuse is lit for something that will not detonate until after the votes are counted.", subject = "both", trigger = EventTrigger.Scheduled(turn = 4), choices = listOf(EventChoice(id = "d_corruption", text = "Make it the issue: the most corrupt administration in history.", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = 0.04), BlocDelta(blocId = BlocId.YOUTH, margin = 0.03), BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = -0.02)), salienceDeltas = mapOf("law_and_order" to 0.03), momentum = 2.0, narrative = 1.0), resultText = "The charge is true and early, and a country at peace and near-prosperity is not listening yet."), EventChoice(id = "d_focus", text = "Stay on the war and the economy: the burglary is a sideshow.", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.03), BlocDelta(blocId = BlocId.SENIORS, margin = 0.02), BlocDelta(blocId = BlocId.YOUTH, margin = -0.02)), momentum = 2.0, narrative = 1.0), resultText = "Discipline keeps you on message, and lets the one scandal that could matter slide by."), EventChoice(id = "r_dismiss", text = "Dismiss and deny: nobody in the White House was involved.", side = CandidateId.REP, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.SENIORS, margin = 0.03), BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.02), BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = -0.02)), momentum = 3.0, narrative = 1.0), resultText = "The stonewall holds through Election Day. What it costs comes due next year.")), oncePerGame = true),
    GameEvent(id = "h72_debate", title = "The Empty Podium", prompt = "The incumbent, far ahead, refuses to debate at all. The challenger demands a stage, an empty chair, anything to close a twenty-point gap. Play the debate that history did or did not hold.", subject = "both", trigger = EventTrigger.Scheduled(turn = 5), choices = listOf(EventChoice(id = "aggressive_case", text = "Prosecute the war and the corruption, hard.", effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.YOUTH, margin = 0.05), BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = 0.04), BlocDelta(blocId = BlocId.SENIORS, margin = -0.02)), momentum = 5.0, narrative = 4.0), resultText = "The passion is real and the base roars, and it mostly reaches people already with you."), EventChoice(id = "reassure_case", text = "Reassure the middle: not a radical, just a decent alternative.", effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.05), BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.03), BlocDelta(blocId = BlocId.YOUTH, margin = -0.02)), momentum = 5.0, narrative = 5.0), resultText = "Looking calm and mainstream is your only path back, and the caricature is stubborn.")), isDebate = true, oncePerGame = true),
    GameEvent(id = "h72_china", title = "Peace Is at Hand", prompt = "Trips to China and Moscow, and Kissinger's late declaration that 'peace is at hand' in Vietnam, wrap the incumbency in the aura of a statesman. The challenger's core issue is being pulled out from under him.", subject = "rep", trigger = EventTrigger.Scheduled(turn = 6), choices = listOf(EventChoice(id = "r_statesman", text = "Run on the world stage: only a proven hand keeps the peace.", side = CandidateId.REP, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.SENIORS, margin = 0.05), BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.04), BlocDelta(blocId = BlocId.YOUTH, margin = -0.02)), momentum = 4.0, narrative = 4.0), resultText = "The statesman frame is unanswerable when the other man promised only to end the war."), EventChoice(id = "r_run_up", text = "Run up the score: contest states no Republican has won in a generation.", side = CandidateId.REP, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.05), BlocDelta(blocId = BlocId.SENIORS, margin = 0.03), BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = 0.02)), momentum = 3.0, narrative = 2.0), resultText = "With the win secure, the map itself becomes the prize: a realignment drawn in one night."), EventChoice(id = "d_hollow", text = "Call it hollow: the war is not over and the peace is a mirage.", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.YOUTH, margin = 0.04), BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = 0.03), BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = -0.03)), momentum = 2.0, narrative = 0.0), resultText = "The skepticism is vindicated within weeks, and arrives at the ballot box far too late.")), oncePerGame = true)
)

val HIST_1968: List<GameEvent> = listOf(
    GameEvent(id = "h68_chicago", title = "The Whole World Is Watching", prompt = "The Democratic convention in Chicago descends into chaos as police battle antiwar protesters in the streets. Humphrey wins the nomination over a party that is tearing itself apart on live television. He starts the fall behind and broke.", subject = "dem", trigger = EventTrigger.Scheduled(turn = 0), choices = listOf(EventChoice(id = "d_distance", text = "Distance yourself: deplore the violence, look to order.", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.SENIORS, margin = 0.04), BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.04), BlocDelta(blocId = BlocId.YOUTH, margin = -0.05)), salienceDeltas = mapOf("law_and_order" to 0.04), momentum = 2.0, narrative = 1.0), resultText = "Reaching for the center calms nervous elders, and drives the young left further from you."), EventChoice(id = "d_heal", text = "Heal the party: bring the antiwar wing back into the tent.", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.YOUTH, margin = 0.06), BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = 0.04), BlocDelta(blocId = BlocId.SENIORS, margin = -0.03)), momentum = 3.0, narrative = 2.0), resultText = "The olive branch begins to close the wound, slowly, with weeks you may not have."), EventChoice(id = "r_order", text = "Own law and order: the party in the streets is their party.", side = CandidateId.REP, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.06), BlocDelta(blocId = BlocId.SENIORS, margin = 0.04), BlocDelta(blocId = BlocId.YOUTH, margin = -0.03)), salienceDeltas = mapOf("law_and_order" to 0.06), momentum = 4.0, narrative = 2.0), resultText = "The contrast with the Chicago chaos is the whole campaign in a single image.")), oncePerGame = true),
    GameEvent(id = "h68_wallace", title = "The Wallace Problem", prompt = "George Wallace's third-party run is pulling working-class whites out of the New Deal coalition and threatens to throw the whole election into the House. His five Deep South states are already gone; the fight is for the Northern blue-collar wards he is raiding.", subject = "both", trigger = EventTrigger.Scheduled(turn = 2), choices = listOf(EventChoice(id = "d_labor", text = "Win labor back: remind them whose party built the middle class.", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.06), BlocDelta(blocId = BlocId.SENIORS, margin = 0.03), BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = -0.02)), salienceDeltas = mapOf("economy" to 0.04), momentum = 4.0, narrative = 3.0), resultText = "The union halls come home late but real, exactly the votes Wallace was renting in the North."), EventChoice(id = "d_left", text = "Court the antiwar left instead: they are the future.", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.YOUTH, margin = 0.05), BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = 0.04), BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = -0.04)), momentum = 2.0, narrative = 1.0), resultText = "The students rally, and the blue-collar defection to Wallace keeps right on bleeding."), EventChoice(id = "r_southern", text = "Run the Southern strategy: undercut Wallace, hold the middle.", side = CandidateId.REP, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.05), BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.02), BlocDelta(blocId = BlocId.BLACK, margin = -0.04)), salienceDeltas = mapOf("law_and_order" to 0.04), momentum = 3.0, narrative = 1.0), resultText = "Peeling the rim South from Wallace builds a new majority, and forfeits the Black vote for a generation.")), oncePerGame = true),
    GameEvent(id = "h68_halt", title = "The Salt Lake City Break", prompt = "Trailing badly, Humphrey finally breaks with Johnson on Vietnam in a nationally televised Salt Lake City speech, calling for a bombing halt. Money and antiwar Democrats start flowing back. The gap begins, at last, to close.", subject = "dem", trigger = EventTrigger.Scheduled(turn = 4), choices = listOf(EventChoice(id = "d_own_it", text = "Make it your own: a Humphrey policy, not a Johnson footnote.", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.YOUTH, margin = 0.06), BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = 0.04), BlocDelta(blocId = BlocId.SENIORS, margin = -0.02)), momentum = 5.0, cash = 6000000.0, narrative = 4.0), resultText = "The declaration of independence electrifies the base, and the surge is on."), EventChoice(id = "d_careful", text = "Thread it carefully: keep the White House on your side.", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.SENIORS, margin = 0.03), BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.02), BlocDelta(blocId = BlocId.YOUTH, margin = -0.02)), momentum = 3.0, narrative = 2.0), resultText = "The caution keeps Johnson from cutting you loose, and blunts the very break that was reviving you."), EventChoice(id = "r_blur", text = "Blur the difference: he is the same failed policy in a new suit.", side = CandidateId.REP, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.04), BlocDelta(blocId = BlocId.SENIORS, margin = 0.03), BlocDelta(blocId = BlocId.YOUTH, margin = -0.02)), momentum = 2.0, narrative = 1.0), resultText = "Denying him a clean break slows the comeback, if only for a while.")), oncePerGame = true),
    GameEvent(id = "h68_debate", title = "The Debate That Wasn't", prompt = "The frontrunner, wary of the medium that beat him in 1960, refuses to debate. The challenger, surging late, would give anything for the split screen. Stage the confrontation the country was denied.", subject = "both", trigger = EventTrigger.Scheduled(turn = 5), choices = listOf(EventChoice(id = "passion", text = "Bring the passion: the Happy Warrior, unleashed on the war and poverty.", effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.YOUTH, margin = 0.05), BlocDelta(blocId = BlocId.BLACK, margin = 0.04), BlocDelta(blocId = BlocId.SENIORS, margin = -0.02)), momentum = 6.0, narrative = 5.0), resultText = "The old fire returns and the coalition remembers why it loved you. The clock is the only enemy left."), EventChoice(id = "steady", text = "Project a steady, statesmanlike command.", effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.SENIORS, margin = 0.05), BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.04), BlocDelta(blocId = BlocId.YOUTH, margin = -0.02)), momentum = 5.0, narrative = 6.0), resultText = "Looking presidential reassures the middle that the chaos is not on your side of the aisle.")), isDebate = true, oncePerGame = true),
    GameEvent(id = "h68_october", title = "The Bombing Halt and the Sabotage", prompt = "Days before the vote, Johnson announces a full bombing halt and peace talks. Humphrey surges. Then the South Vietnamese suddenly pull out of the talks, and rumors swirl that Nixon's people quietly told Saigon to wait for a better deal. The race freezes on a knife's edge.", subject = "both", trigger = EventTrigger.Scheduled(turn = 6), choices = listOf(EventChoice(id = "d_ride", text = "Ride the halt: peace is breaking out, finish the surge.", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.YOUTH, margin = 0.05), BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.03), BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.02)), momentum = 5.0, narrative = 3.0), resultText = "The peace momentum is real and the polls close by the hour, with days that may not be enough."), EventChoice(id = "d_expose", text = "Expose the sabotage: they are playing politics with peace.", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = 0.04), BlocDelta(blocId = BlocId.YOUTH, margin = 0.03), BlocDelta(blocId = BlocId.SENIORS, margin = -0.02)), momentum = 2.0, narrative = -2.0), resultText = "The charge is explosive and unprovable in time, and stirring it risks looking desperate."), EventChoice(id = "r_deny", text = "Deny everything: keep the frozen talks frozen.", side = CandidateId.REP, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.04), BlocDelta(blocId = BlocId.SENIORS, margin = 0.03), BlocDelta(blocId = BlocId.YOUTH, margin = -0.03)), momentum = 3.0, narrative = 0.0), resultText = "The stall holds just long enough. The halt fizzles, and the lead survives to Election Day."), EventChoice(id = "r_peace", text = "Promise a secret plan: you will end the war on better terms.", side = CandidateId.REP, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.04), BlocDelta(blocId = BlocId.SENIORS, margin = 0.03), BlocDelta(blocId = BlocId.YOUTH, margin = -0.02)), momentum = 3.0, narrative = 2.0), resultText = "The vague assurance robs the halt of its power: why settle now if a better deal waits?")), oncePerGame = true)
)

val HIST_1964: List<GameEvent> = listOf(
    GameEvent(id = "h64_extremism", title = "Extremism in the Defense of Liberty", prompt = "Accepting the nomination, Goldwater declares that 'extremism in the defense of liberty is no vice.' The line thrills the movement that drafted him and terrifies the moderate suburbs the party needs. The whole fall hinges on which reaction wins.", subject = "rep", trigger = EventTrigger.Scheduled(turn = 0), choices = listOf(EventChoice(id = "r_conviction", text = "Double down: a choice, not an echo, no apologies.", side = CandidateId.REP, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.05, enthusiasm = 0.03), BlocDelta(blocId = BlocId.SENIORS, margin = 0.02), BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = -0.05)), momentum = 3.0, narrative = -2.0), resultText = "The base is electrified and the suburbs recoil. The conviction is real and so is the ceiling."), EventChoice(id = "r_reassure", text = "Reassure the middle: temperance, prudence, a safe pair of hands.", side = CandidateId.REP, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.05), BlocDelta(blocId = BlocId.SENIORS, margin = 0.03), BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = -0.03)), momentum = 2.0, narrative = 3.0), resultText = "Softening the edges wins a second look from moderates, and dampens the movement's fire."), EventChoice(id = "d_paint", text = "Paint him as reckless: too extreme for the mainstream.", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.05), BlocDelta(blocId = BlocId.SENIORS, margin = 0.04), BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = -0.01)), momentum = 4.0, narrative = 3.0), resultText = "The reckless frame does the work for you, straight from your opponent's own mouth.")), oncePerGame = true),
    GameEvent(id = "h64_daisy", title = "The Daisy Ad", prompt = "A little girl plucks daisy petals; a countdown; a mushroom cloud. It airs exactly once and never names Goldwater, because it does not have to. The most famous attack ad ever made drops the nuclear question onto every living room.", subject = "dem", trigger = EventTrigger.Scheduled(turn = 2), choices = listOf(EventChoice(id = "d_air", text = "Let it breathe: air it once, let the outrage carry it.", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.06), BlocDelta(blocId = BlocId.SENIORS, margin = 0.04), BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = -0.02)), salienceDeltas = mapOf("law_and_order" to 0.03), momentum = 4.0, narrative = 3.0), resultText = "Pulling it after one airing only multiplies the coverage. The stakes are set, in your favor."), EventChoice(id = "d_highroad", text = "Take the high road: govern above the fear.", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = 0.04), BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.02), BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = -0.01)), momentum = 2.0, narrative = 4.0), resultText = "The statesmanlike restraint burnishes the presidential image, and leaves a devastating weapon in its holster."), EventChoice(id = "r_victim", text = "Cry foul: a smear that says nothing about the issues.", side = CandidateId.REP, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.04), BlocDelta(blocId = BlocId.SENIORS, margin = 0.02), BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = -0.03)), momentum = 2.0, narrative = 1.0), resultText = "Protesting the ad keeps the mushroom cloud on every screen for another news cycle.")), oncePerGame = true),
    GameEvent(id = "h64_civilrights", title = "The Civil Rights Realignment", prompt = "Johnson has signed the Civil Rights Act and privately told an aide the Democrats have lost the South for a generation. Goldwater, one of the few Republicans to vote against it, is suddenly competitive across the Deep South for the first time in a century.", subject = "both", trigger = EventTrigger.Scheduled(turn = 3), choices = listOf(EventChoice(id = "d_moral", text = "Stand on principle: the Act is right, whatever it costs.", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.BLACK, margin = 0.08), BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = 0.03), BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = -0.04)), salienceDeltas = mapOf("race_policing" to 0.05), momentum = 3.0, narrative = 4.0), resultText = "History will vindicate you and the Deep South will punish you, exactly as the President predicted."), EventChoice(id = "d_hold_border", text = "Hold the border South: the New Deal still pays the bills.", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.05), BlocDelta(blocId = BlocId.SENIORS, margin = 0.03), BlocDelta(blocId = BlocId.BLACK, margin = -0.01)), salienceDeltas = mapOf("economy" to 0.04), momentum = 3.0, narrative = 2.0), resultText = "Prosperity keeps the upper South blue even as the Deep South goes, a coalition worth defending."), EventChoice(id = "r_deepsouth", text = "Sweep the Deep South: build the new conservative majority.", side = CandidateId.REP, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.06), BlocDelta(blocId = BlocId.SENIORS, margin = 0.02), BlocDelta(blocId = BlocId.BLACK, margin = -0.06)), momentum = 3.0, narrative = 0.0), resultText = "You win five states no Republican has carried since Reconstruction, and lose everywhere else by miles.")), oncePerGame = true),
    GameEvent(id = "h64_debate", title = "The Front-Runner Declines", prompt = "Far ahead and unwilling to elevate his challenger, the President declines to debate. In the counterfactual, the two men finally share a stage. Make the case the country never got to weigh live.", subject = "both", trigger = EventTrigger.Scheduled(turn = 5), choices = listOf(EventChoice(id = "steady_hand", text = "Run as the steady hand: continuity, prosperity, peace.", effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.05), BlocDelta(blocId = BlocId.SENIORS, margin = 0.05), BlocDelta(blocId = BlocId.YOUTH, margin = -0.01)), momentum = 6.0, narrative = 6.0), resultText = "Reassurance is the whole ballgame in a landslide year, and you deliver it in full."), EventChoice(id = "great_society", text = "Sell the Great Society: a bolder, fairer America.", effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.BLACK, margin = 0.05), BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = 0.04), BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = -0.02)), salienceDeltas = mapOf("healthcare" to 0.04), momentum = 5.0, narrative = 5.0), resultText = "The vision energizes the coalition and hands your opponent a target, and the mandate is worth it.")), isDebate = true, oncePerGame = true),
    GameEvent(id = "h64_socialsecurity", title = "The Social Security Scare", prompt = "Goldwater has mused about making Social Security voluntary, and the Democrats have turned it into a torch in the retirement communities of Florida and the industrial North. Seniors are frightened. Steady the ticket or stand on principle.", subject = "rep", trigger = EventTrigger.Scheduled(turn = 6), choices = listOf(EventChoice(id = "r_clarify", text = "Clarify fast: you will save the program, not end it.", side = CandidateId.REP, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.SENIORS, margin = 0.05), BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.02), BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = -0.02)), momentum = 3.0, narrative = 2.0), resultText = "The reassurance stops the panic in the retiree belts, at the price of the purist glow."), EventChoice(id = "r_principle", text = "Stand on principle: government has grown too big, period.", side = CandidateId.REP, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.04), BlocDelta(blocId = BlocId.SENIORS, margin = -0.06), BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = -0.03)), salienceDeltas = mapOf("taxes" to 0.04), momentum = 1.0, narrative = -3.0), resultText = "The base cheers the consistency, and every senior hears a threat to the check that keeps the lights on."), EventChoice(id = "d_hammer", text = "Hammer it home: he will take your Social Security away.", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.SENIORS, margin = 0.06), BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.03), BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = -0.01)), salienceDeltas = mapOf("healthcare" to 0.03), momentum = 3.0, narrative = 1.0), resultText = "The fear does the turnout work for you across every retirement community in the country.")), oncePerGame = true)
