val HIST_1960: List<GameEvent> = listOf(
    GameEvent(id = "h60_religion", title = "The Religion Question", prompt = "No Catholic has ever been elected president, and Protestant ministers warn that a Catholic would take orders from Rome. Kennedy has to decide whether to confront the whisper campaign head-on or hope it fades.", subject = "dem", trigger = EventTrigger.Scheduled(turn = 0), choices = listOf(EventChoice(id = "d_houston", text = "Face it in Houston: an America where church and state are absolute.", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = 0.05), BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.04), BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = -0.02)), momentum = 4.0, narrative = 5.0), resultText = "Meeting the ministers directly turns the liability into a display of grace under fire."), EventChoice(id = "d_mobilize", text = "Quietly mobilize Catholic turnout in the big cities.", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.05), BlocDelta(blocId = BlocId.SENIORS, margin = 0.02), BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = -0.02)), momentum = 3.0, narrative = 1.0), resultText = "The urban Catholic wards surge, and the Bible Belt hardens against you all the same."), EventChoice(id = "r_stayclean", text = "Stay above it: refuse to make religion an issue.", side = CandidateId.REP, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.04), BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = 0.03), BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = -0.02)), momentum = 2.0, narrative = 3.0), resultText = "Keeping your hands clean plays well with the middle, while surrogates work the back channels.")), oncePerGame = true),
    GameEvent(id = "h60_debate", title = "The Great Debate", prompt = "Seventy million Americans watch the first televised presidential debate. One man is tanned and rested; the other is pale, sweating, recovering from illness and refusing makeup. Radio listeners will call it a draw. Television will not. Own the new medium.", subject = "both", trigger = EventTrigger.Scheduled(turn = 2), choices = listOf(EventChoice(id = "look_the_part", text = "Master the camera: calm, vigorous, presidential.", effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.06), BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = 0.05), BlocDelta(blocId = BlocId.SENIORS, margin = 0.03), BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = -0.01)), momentum = 8.0, narrative = 9.0), resultText = "Image becomes substance. The split screen alone moves a nation that has never voted by television before."), EventChoice(id = "win_substance", text = "Win on experience: eight years at the center of power.", effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.SENIORS, margin = 0.05), BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.04), BlocDelta(blocId = BlocId.YOUTH, margin = -0.02)), momentum = 5.0, narrative = 3.0), resultText = "You win the argument on the merits, and the audience remembers the sweat more than the syllogism.")), isDebate = true, oncePerGame = true),
    GameEvent(id = "h60_king", title = "The Call to Coretta", prompt = "Martin Luther King Jr. is jailed in Georgia and his wife fears for his life. Kennedy can place a sympathetic phone call to Coretta Scott King, a gesture that could move Black voters North and enrage white Democrats in the South.", subject = "dem", trigger = EventTrigger.Scheduled(turn = 3), choices = listOf(EventChoice(id = "d_call", text = "Make the call: a private word of comfort that will not stay private.", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.BLACK, margin = 0.09), BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = 0.03), BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = -0.04)), salienceDeltas = mapOf("race_policing" to 0.04), momentum = 3.0, narrative = 3.0), resultText = "Black churches swing hard your way, and the Solid South grows nervous about its own nominee."), EventChoice(id = "d_caution", text = "Stay cautious: do nothing to spook the Southern base.", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.04), BlocDelta(blocId = BlocId.SENIORS, margin = 0.02), BlocDelta(blocId = BlocId.BLACK, margin = -0.05)), momentum = 1.0, narrative = 0.0), resultText = "The South stays quiet, and a historic opening with Black voters slips by unclaimed."), EventChoice(id = "r_court_black", text = "Court Black voters yourself: the party of Lincoln still has a claim.", side = CandidateId.REP, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.BLACK, margin = 0.05), BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.02), BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = -0.02)), momentum = 2.0, narrative = 1.0), resultText = "The Lincoln appeal keeps a share of the Black vote that your rival is about to lose forever.")), oncePerGame = true),
    GameEvent(id = "h60_experience", title = "Experience Versus Vigor", prompt = "The sitting Vice President runs on eight years of experience and a promise to stand up to Khrushchev. The young senator runs on vigor and a warning about a missile gap. The country weighs steadiness against a new generation.", subject = "both", trigger = EventTrigger.Scheduled(turn = 4), choices = listOf(EventChoice(id = "d_newgen", text = "Summon a new generation: get the country moving again.", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.YOUTH, margin = 0.06), BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = 0.04), BlocDelta(blocId = BlocId.SENIORS, margin = -0.03)), momentum = 4.0, narrative = 4.0), resultText = "The generational call thrills the young and the restless, and unsettles voters who prize a steady hand."), EventChoice(id = "d_missilegap", text = "Press the missile gap: we have fallen behind the Soviets.", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.04), BlocDelta(blocId = BlocId.SENIORS, margin = 0.03), BlocDelta(blocId = BlocId.YOUTH, margin = -0.01)), salienceDeltas = mapOf("law_and_order" to 0.03), momentum = 3.0, narrative = 2.0), resultText = "Running to the hawkish side of an incumbent is audacious, and it lands with a Cold War electorate."), EventChoice(id = "r_experience", text = "Run on experience: a tested hand in a dangerous world.", side = CandidateId.REP, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.SENIORS, margin = 0.05), BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.03), BlocDelta(blocId = BlocId.YOUTH, margin = -0.03)), momentum = 3.0, narrative = 3.0), resultText = "The experience frame reassures the cautious, and can read as yesterday against a telegenic challenger.")), oncePerGame = true),
    GameEvent(id = "h60_fifty_states", title = "The Fifty-State Pledge", prompt = "Nixon has rashly promised to campaign in all fifty states, including brand-new Alaska and Hawaii. A knee injury and an infection cost him two weeks in the hospital, and the pledge now means exhausting detours to states worth a handful of votes.", subject = "rep", trigger = EventTrigger.Scheduled(turn = 5), choices = listOf(EventChoice(id = "r_keep", text = "Keep the promise: fly to Alaska, honor your word.", side = CandidateId.REP, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.SENIORS, margin = 0.03), BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.02), BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = -0.03)), momentum = -2.0, narrative = 1.0), resultText = "The integrity plays, and the wasted days in tiny states are days not spent in Illinois and Texas."), EventChoice(id = "r_break", text = "Break it quietly: pour the final week into the big battlegrounds.", side = CandidateId.REP, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.05), BlocDelta(blocId = BlocId.SUBURBAN_WOMEN, margin = 0.03), BlocDelta(blocId = BlocId.SENIORS, margin = -0.01)), momentum = 4.0, narrative = 1.0), resultText = "Concentrating the closing blitz where the votes are is the smart play, and the broken pledge stings a little."), EventChoice(id = "d_bigstates", text = "Lock the big states: run the machine in the industrial North.", side = CandidateId.DEM, effects = EventEffect(blocDeltas = listOf(BlocDelta(blocId = BlocId.NONCOLLEGE_WHITE, margin = 0.05), BlocDelta(blocId = BlocId.BLACK, margin = 0.03), BlocDelta(blocId = BlocId.COLLEGE_WHITE, margin = -0.01)), momentum = 3.0, narrative = 2.0), resultText = "The big-state machines grind out the margins that decide a race this close.")), oncePerGame = true)
)

